// Modular exponentiation: (base^exp) % mod
fn modPow(base: u64, exp: u64, mod: u64) u64 {
    var result: u64 = 1;
    var b = base % mod;
    var e = exp;
    while (e > 0) : (e /= 2) {
        if ((e & 1) != 0) {
            result = (result * b) % mod;
        }
        b = (b * b) % mod;
    }
    return result;
}

