    const allocator = std.heap.page_allocator;

    // Open and read the input file
    const file = try std.fs.cwd().openFile("input.txt", .{ .read = true });
    defer file.close();

    const buffer = try file.readToEndAlloc(allocator, 1024);
    defer allocator.free(buffer);

    // Parse row and column from the input string
    // Expected format: "... (row R, column C)"
    var row: u64 = 0;
    var col: u64 = 0;
    var found_row = false;
    var found_col = false;

    var it = std.mem.tokenizeAny(u8, buffer, " ,()");
    while (it.next()) |token| {
        if (std.mem.eql(u8, token, "row")) {
            const next_token = it.next() orelse continue;
            row = try std.fmt.parseInt(u64, next_token, 10);
            found_row = true;
        } else if (std.mem.eql(u8, token, "column")) {
            const next_token = it.next() orelse continue;
            col = try std.fmt.parseInt(u64, next_token, 10);
            found_col = true;
        }
    }

    if (!found_row or !found_col) {
        try stdout.print("Error: Could not parse row and column from input.txt\n", .{});
        return error.ParseError;
    }

    // Calculate the 1-based index of the target cell (row, col)
    // The sum of row and column for a diagonal is `r + c`.
    // The number of elements in diagonals before `r+c` is `(r+c-2)*(r+c-1)/2`.
    // Within the current diagonal, the position is `c`.
    const diagonal_sum = row + col;
    const codes_before_diagonal = (diagonal_sum - 2) * (diagonal_sum - 1) / 2;
    const target_index = codes_before_diagonal + col;

    // Code generation parameters
    const initial_code: u64 = 20151125;
    const multiplier: u64 = 252533;
    const modulus: u64 = 33554393;

    // Calculate the code
    // The target_index is 1-based, so we need multiplier^(target_index - 1)
    const exponent = target_index - 1;
    const factor = modPow(multiplier, exponent, modulus);
    const final_code = (initial_code * factor) % modulus;

    try stdout.print("{d}\n", .{final_code});
}

