import React, { useState, useRef, useEffect, useMemo, useCallback, ChangeEvent, KeyboardEvent } from 'react';
import { FixedSizeList as List } from 'react-window';
import AutoSizer from 'react-virtualized-auto-sizer';

interface InputProps {
  options: string[];
  value?: string;
  onChange?: (value: string) => void;
  onValidate?: (isValid: boolean) => void;
  placeholder?: string;
  debounceTime?: number; // For optimizing filtering on large lists
}

const ITEM_HEIGHT = 35; // Height of each item in the dropdown
const MAX_VISIBLE_ITEMS = 6; // Maximum number of items to show before scrolling

export const Input: React.FC<InputProps> = ({
  options,
  value: controlledValue,
  onChange,
  onValidate,
  placeholder = 'Type to search...',
  debounceTime = 300,
}) => {
  const [inputValue, setInputValue] = useState<string>(controlledValue || '');
  const [filteredOptions, setFilteredOptions] = useState<string[]>([]);
  const [showDropdown, setShowDropdown] = useState<boolean>(false);
  const [highlightedIndex, setHighlightedIndex] = useState<number>(-1);
  const [isValid, setIsValid] = useState<boolean>(true);
  const [isFocused, setIsFocused] = useState<boolean>(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<List>(null);

  // Effect to update internal state if controlledValue changes externally
  useEffect(() => {
    if (controlledValue !== undefined && controlledValue !== inputValue) {
      setInputValue(controlledValue);
    }
  }, [controlledValue]);

  // Debounced filtering logic
  useEffect(() => {
    const handler = setTimeout(() => {
      const lowerInput = inputValue.toLowerCase().trim();
      if (!lowerInput) {
        setFilteredOptions([]);
        setShowDropdown(false);
        setHighlightedIndex(-1);
        return;
      }

      const newFilteredOptions = options.filter(opt =>
        opt.toLowerCase().includes(lowerInput)
      );
      setFilteredOptions(newFilteredOptions);
      setShowDropdown(newFilteredOptions.length > 0);
      setHighlightedIndex(-1); // Reset highlight when input changes
    }, debounceTime);

    return () => {
      clearTimeout(handler);
    };
  }, [inputValue, options, debounceTime]);

  // Validation logic
  useEffect(() => {
    const currentIsValid = options.some(
      (opt) => opt.toLowerCase() === inputValue.toLowerCase().trim()
    ) || inputValue.trim() === ''; // Valid if empty or matches an option
    setIsValid(currentIsValid);
    onValidate?.(currentIsValid);
  }, [inputValue, options, onValidate]);

  // Handle clicks outside to close the dropdown
  const handleClickOutside = useCallback(
    (event: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target as Node)
      ) {
        setShowDropdown(false);
        setHighlightedIndex(-1);
        setIsFocused(false);
      }
    },
    []
  );

  useEffect(() => {
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [handleClickOutside]);

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setInputValue(val);
    onChange?.(val);
  };

  const handleOptionSelect = (option: string) => {
    setInputValue(option);
    onChange?.(option);
    setShowDropdown(false);
    setHighlightedIndex(-1);
    inputRef.current?.focus(); // Keep focus on input after selection
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (!showDropdown || filteredOptions.length === 0) {
      return;
    }

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHighlightedIndex((prev) => {
        const newIndex = prev < filteredOptions.length - 1 ? prev + 1 : 0;
        listRef.current?.scrollToItem(newIndex, 'smart');
        return newIndex;
      });
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlightedIndex((prev) => {
        const newIndex = prev > 0 ? prev - 1 : filteredOptions.length - 1;
        listRef.current?.scrollToItem(newIndex, 'smart');
        return newIndex;
      });
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (highlightedIndex >= 0 && highlightedIndex < filteredOptions.length) {
        handleOptionSelect(filteredOptions[highlightedIndex]);
      } else if (filteredOptions.length === 1) { // Auto-select if only one option
        handleOptionSelect(filteredOptions[0]);
      }
    } else if (e.key === 'Escape') {
      setShowDropdown(false);
      setHighlightedIndex(-1);
      inputRef.current?.blur();
    }
  };

  const dropdownHeight = Math.min(filteredOptions.length, MAX_VISIBLE_ITEMS) * ITEM_HEIGHT;

  const Row = useCallback(
    ({ index, style }: { index: number; style: React.CSSProperties }) => {
      const option = filteredOptions[index];
      const isHighlighted = index === highlightedIndex;

      return (
        <div
          style={{
            ...style,
            backgroundColor: isHighlighted ? '#f0f0f0' : '#fff',
            padding: '8px',
            cursor: 'pointer',
            borderBottom: index < filteredOptions.length - 1 ? '1px solid #eee' : 'none',
            display: 'flex',
            alignItems: 'center',
