    <div
      ref={containerRef}
      style={{ position: 'relative', width: '100%', maxWidth: 400 }}
      role="combobox"
      aria-haspopup="listbox"
      aria-expanded={showDropdown}
    >
      <input
        ref={inputRef}
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        onFocus={() => {
          setIsFocused(true);
          if (filteredOptions.length > 0) {
            setShowDropdown(true);
          }
        }}
        onBlur={() => {
          // Delay hiding dropdown to allow click events on options to fire
          setTimeout(() => {
            setIsFocused(false);
            // Only hide dropdown if input is invalid and not focused
            if (!isValid && inputValue.trim() !== '') {
              setShowDropdown(false);
              setHighlightedIndex(-1);
            }
          }, 100);
        }}
        placeholder={placeholder}
        style={{
          width: '100%',
          padding: '8px 12px',
          fontSize: 16,
          borderRadius: 4,
          border: `2px solid ${isValid ? '#ccc' : 'red'}`,
          outline: isFocused ? '2px solid #3399FF' : 'none',
          boxSizing: 'border-box',
        }}
        aria-autocomplete="list"
        aria-controls="dropdown-listbox"
        aria-activedescendant={highlightedIndex >= 0 ? `option-${highlightedIndex}` : undefined}
      />

      {showDropdown && filteredOptions.length > 0 && (
        <div
          role="listbox"
          id="dropdown-listbox"
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            right: 0,
            maxHeight: dropdownHeight,
            border: '1px solid #ccc',
            borderTop: 'none',
            backgroundColor: '#fff',
            zIndex: 1000,
            borderRadius: '0 0 4px 4px',
            boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
            overflow: 'hidden', // Ensure virtualization works correctly
          }}
        >
          <AutoSizer disableHeight>
            {({ width }) => (
              <List
                ref={listRef}
                height={dropdownHeight}
                itemCount={filteredOptions.length}
                itemSize={ITEM_HEIGHT}
                width={width}
                overscanCount={5} // Render a few extra items above/below visible area
              >
                {Row}
              </List>
            )}
          </AutoSizer>
        </div>
      )}
    </div>
  );
};

// Example Usage
/*
