    setFruitValue(value);
  };

  const handleFruitValidation = (isValid: boolean) => {
    setIsFruitValid(isValid);
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Custom Input Component</h1>

      <div style={{ marginBottom: 40 }}>
        <h3>Fruits (with validation)</h3>
        <Input
          options={fruits}
          value={fruitValue}
          onChange={handleFruitChange}
          onValidate={handleFruitValidation}
          placeholder="Select a fruit..."
        />
        {!isFruitValid && fruitValue.trim() !== '' && (
          <p style={{ color: 'red', fontSize: '0.9em' }}>Please select a valid fruit from the list.</p>
        )}
        <p>Current fruit input: {fruitValue}</p>
      </div>

