    writeGpioFile("/sys/class/gpio/export", M1_IN1); // Export M1_IN1
    writeGpioFile("/sys/class/gpio/export", M1_IN2); // Export M1_IN2
    writeGpioFile("/sys/class/gpio/export", M2_IN1); // Export M2_IN1
    writeGpioFile("/sys/class/gpio/export", M2_IN2); // Export M2_IN2

