    writeGpioFile("/sys/class/gpio/gpio" + M1_IN2 + "/direction", "out"); // Set M1_IN2 as output
    writeGpioFile("/sys/class/gpio/gpio" + M2_IN1 + "/direction", "out"); // Set M2_IN1 as output
