    writeGpioFile("/sys/class/gpio/gpio" + M2_IN2 + "/value", "1"); // Set M2_IN2 HIGH

    std::cout << "Motors running: Motor 1 Forward, Motor 2 Backward for 3 seconds." << std::endl;
    sleep(3); // Let motors run for 3 seconds

    // --- 4. Stop Motors ---
    // To stop the motors, set both IN pins for each motor to LOW.
