            btnReadData = new Button { Text = "Read Data", Location = new System.Drawing.Point(180, 120), Width = 120 };

            // ListBox
            lstStudents = new ListBox { Location = new System.Drawing.Point(20, 160), Size = new System.Drawing.Size(280, 240) };

