            // Event Handlers
            btnWriteData.Click += BtnWriteData_Click;
            btnReadData.Click += BtnReadData_Click;
        }

        // Handles the "Write Data" button click event
        private void BtnWriteData_Click(object sender, EventArgs e)
        {
            // Validate user inputs
            string errorMessage = "";
            errorMessage += Validator.IsPresent(txtStudentID.Text, "Student ID");
            errorMessage += Validator.IsInt32(txtStudentID.Text, "Student ID");
            errorMessage += Validator.IsPresent(txtName.Text, "Name");
            errorMessage += Validator.IsPresent(txtGPA.Text, "GPA");
            errorMessage += Validator.IsDecimal(txtGPA.Text, "GPA");
            errorMessage += Validator.IsWithinRange(txtGPA.Text, "GPA", 0m, 4m); // Assuming GPA is between 0 and 4

            if (!string.IsNullOrEmpty(errorMessage))
            {
                MessageBox.Show(errorMessage, "Input Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            try
            {
                // Create a new Student object from the input fields
                Student newStudent = new Student
                {
                    StudentID = int.Parse(txtStudentID.Text),
                    Name = txtName.Text.Trim(),
                    GPA = decimal.Parse(txtGPA.Text)
                };

                // Check for duplicate Student ID before adding
                if (students.Exists(s => s.StudentID == newStudent.StudentID))
                {
                    MessageBox.Show("A student with this ID already exists. Please use a unique ID.", "Duplicate ID", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                students.Add(newStudent); // Add the new student to the in-memory list
                StudentDB.SaveStudents(students); // Save the entire list to the binary file

                MessageBox.Show("Student data written successfully!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);

                ClearInputFields(); // Clear the input fields after successful write
                DisplayStudents(); // Refresh the ListBox
            }
            catch (Exception ex)
            {
                MessageBox.Show($"An error occurred while writing data: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
