        {
            lstStudents.Items.Clear();
            if (students.Count == 0)
            {
                lstStudents.Items.Add("No student data available.");
            }
            else
            {
                foreach (Student student in students)
                {
                    lstStudents.Items.Add(student.ToString());
                }
            }
        }

        // Helper method to clear input fields
