```cpp
#include <SPI.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define JOYSTICK1_X A0
#define JOYSTICK1_Y A1
#define JOYSTICK2_X A2
#define JOYSTICK2_Y A3

// Define the pin for the restart button
#define RESTART_BUTTON_PIN 7 // Using digital pin 7 for the restart button

const unsigned long PADDLE_RATE = 33;
const unsigned long BALL_RATE = 40;
const uint8_t PADDLE_HEIGHT = 8;
const uint8_t BALL_SIZE = 3;

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 32

#define OLED_RESET 4
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void drawCourt();

// Game state variables (made global or passed to restart function)
uint8_t ball_x = 64, ball_y = 16;
int8_t ball_dir_x = 1, ball_dir_y = 1; // Changed to int8_t to allow negative values
unsigned long ball_update;

unsigned long paddle_update;
const uint8_t CPU_X = 12;
uint8_t cpu_y = 8;

const uint8_t PLAYER_X = 115;
uint8_t player_y = 8;

// Function to reset game state
void restartGame() {
  // Reset ball position and direction
  ball_x = 64;
  ball_y = 16;
  ball_dir_x = 1;
  ball_dir_y = 1;

  // Reset paddle positions
  cpu_y = 8;
  player_y = 8;

  // Clear display and redraw initial game elements
  display.clearDisplay();
  drawCourt();
  display.fillRect(ball_x, ball_y, BALL_SIZE, BALL_SIZE, WHITE); // Draw initial ball
  display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, WHITE);    // Draw initial CPU paddle
  display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE); // Draw initial player paddle
  display.display();

  // Reset timers to prevent immediate movement after restart
  ball_update = millis();
  paddle_update = millis();
}

void setup() {
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.display();
  unsigned long start = millis();

  // Configure the restart button pin with internal pull-up resistor
  pinMode(RESTART_BUTTON_PIN, INPUT_PULLUP);

  display.clearDisplay();
  drawCourt();

  while (millis() - start < 2000);

  display.display();

  ball_update = millis();
  paddle_update = ball_update;
}

void loop() {
  // Check if the restart button is pressed (LOW when pressed due to INPUT_PULLUP)
  if (digitalRead(RESTART_BUTTON_PIN) == LOW) {
    delay(50); // Simple debounce delay
    if (digitalRead(RESTART_BUTTON_PIN) == LOW) { // Confirm button is still pressed
      restartGame(); // Call the restart function
      // Wait for the button to be released to prevent multiple restarts
      while (digitalRead(RESTART_BUTTON_PIN) == LOW) {
        delay(10);
      }
    }
  }

  bool update = false;
  unsigned long time = millis();

  int joy1_x = analogRead(JOYSTICK1_X);
  int joy1_y = analogRead(JOYSTICK1_Y);
  int joy2_x = analogRead(JOYSTICK2_X);
  int joy2_y = analogRead(JOYSTICK2_Y);

  if (time > ball_update) {
    uint8_t new_x = ball_x + ball_dir_x;
    uint8_t new_y = ball_y + ball_dir_y;

    if (new_y == 0 || new_y == 31 - BALL_SIZE) {
      ball_dir_y = -ball_dir_y;
      new_y += ball_dir_y + ball_dir_y;
    }

    if (new_x == CPU_X && new_y >= cpu_y && new_y <= cpu_y + PADDLE_HEIGHT) {
      ball_dir_x = -ball_dir_x;
      new_x += ball_dir_x + ball_dir_x;
    }

    if (new_x == PLAYER_X && new_y >= player_y && new_y <= player_y + PADDLE_HEIGHT) {
      ball_dir_x = -ball_dir_x;
      new_x += ball_dir_x + ball_dir_x;
    }

    display.fillRect(ball_x, ball_y, BALL_SIZE, BALL_SIZE, BLACK);
    display.fillRect(new_x, new_y, BALL_SIZE, BALL_SIZE, WHITE);
    ball_x = new_x;
    ball_y = new_y;

    ball_update += BALL_RATE;

    update = true;
  }

  if (time > paddle_update) {
    paddle_update += PADDLE_RATE;

    display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, BLACK);
    if (joy1_y < 400) {
      cpu_y -= 1;
    }
    if (joy1_y > 600) {
      cpu_y += 1;
    }
    if (cpu_y < 1)
      cpu_y = 1;
    if (cpu_y + PADDLE_HEIGHT > 31)
      cpu_y = 31 - PADDLE_HEIGHT;
    display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, WHITE);

    display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, BLACK);
    if (joy2_y < 400) {
      player_y -= 1;
    }
    if (joy2_y > 600) {
      player_y += 1;
    }
    if (player_y < 1)
      player_y = 1;
    if (player_y + PADDLE_HEIGHT > 31)
      player_y = 31 - PADDLE_HEIGHT;
    display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE);

    update = true;
  }

  if (update)
    display.display();
}

void drawCourt() {
  display.drawRect(0, 0, 128, 32, WHITE);
}
```

**Explanation of changes:**

1.  **`#define RESTART_BUTTON_PIN 7`**: A new constant is defined for the digital pin connected to the restart button. You can change `7` to any available digital pin.
2.  **`pinMode(RESTART_BUTTON_PIN, INPUT_PULLUP);`**: In `setup()`, this line configures the chosen pin. `INPUT_PULLUP` activates the microcontroller's internal pull-up resistor, meaning the pin will be HIGH by default. When the button is pressed, it connects the pin to GND, making the pin LOW. This simplifies wiring as you don't need an external resistor.
3.  **`int8_t ball_dir_x = 1, ball_dir_y = 1;`**: Changed `uint8_t` to `int8_t` for `ball_dir_x` and `ball_dir_y`. This is crucial because `uint8_t` (unsigned 8-bit integer) cannot hold negative values. When `ball_dir_x` or `ball_dir_y` becomes `-1`, it would wrap around to `255` if it were `uint8_t`, causing incorrect ball movement.
4.  **`restartGame()` function**: I've encapsulated the restart logic into a separate function `restartGame()`. This makes the `loop()` cleaner and the restart logic more modular.
    *   It resets `ball_x`, `ball_y`, `ball_dir_x`, `ball_dir_y` to their initial values.
    *   It resets `cpu_y` and `player_y` to their initial values.
    *   It clears the display, redraws the court, and then redraws the initial positions of the ball and paddles. This ensures the screen is properly refreshed after a restart.
    *   It resets `ball_update` and `paddle_update` to `millis()`. This is important to prevent the ball or paddles from making a large jump immediately after a restart if a long time has passed since their last update.
5.  **Button check in `loop()`**:
    *   `if (digitalRead(RESTART_BUTTON_PIN) == LOW)`: This checks if the button is pressed. Since `INPUT_PULLUP` is used, the pin reads `LOW` when the button is pressed.
