/**
 * bcrypt.compareをPromiseでラップするヘルパー関数
 * @param plainText 比較する平文パスワード
 * @param hashedPassword ハッシュ化されたパスワード
 * @returns パスワードが一致すればtrue、そうでなければfalse
 * @throws 内部サーバーエラーが発生した場合
 */
async function comparePassword(
  plainText: string,
  hashedPassword: string
): Promise<boolean> {
  return new Promise((resolve, reject) => {
    bcrypt.compare(plainText, hashedPassword, (err, result) => {
      if (err) {
        // bcrypt内部エラーはサーバーエラーとして扱う
        return reject(new Error("パスワード比較中に内部エラーが発生しました"));
      }
      resolve(result);
    });
  });
}

