// Function to perform linear interpolation
// x_original: sorted vector of original x-coordinates
// y_original: vector of original y-coordinates corresponding to x_original
// x_target: the x-coordinate at which to interpolate y
double linear_interpolate(const std::vector<double>& x_original, const std::vector<double>& y_original, double x_target) {
    // Handle edge cases: extrapolation
    if (x_target <= x_original.front()) {
        return y_original.front();
    }
    if (x_target >= x_original.back()) {
        return y_original.back();
    }

    // Find the interval [x_i, x_{i+1}] that contains x_target
    // Since x_original is assumed to be sorted and equally spaced (from np.arange),
    // we can directly calculate the index.
    // For general sorted x_original, std::upper_bound would be more robust.

    // Assuming x_original is 0, 1, 2, ..., N-1
    // The index i such that x_original[i] <= x_target < x_original[i+1]
    int i = static_cast<int>(x_target); 

    // Ensure i is within bounds for interpolation
    if (i < 0) i = 0;
    if (i >= x_original.size() - 1) i = x_original.size() - 2;

    double x0 = x_original[i];
    double y0 = y_original[i];
    double x1 = x_original[i+1];
    double y1 = y_original[i+1];

    // Linear interpolation formula
    return y0 + (y1 - y0) * ((x_target - x0) / (x1 - x0));
}

// Function to generate linearly spaced points (emulates numpy.linspace)
std::vector<double> linspace(double start, double end, int num_points) {
    std::vector<double> result(num_points);
    if (num_points == 0) {
        return result;
    }
    if (num_points == 1) {
        result[0] = start;
        return result;
    }

    double step = (end - start) / (num_points - 1);
    for (int i = 0; i < num_points; ++i) {
        result[i] = start + i * step;
    }
    return result;
}

