double interp1d_point(double x_target, const std::vector<double>& x_original, const std::vector<double>& y_original) {
    // Handle edge cases: x_target outside the original range
    if (x_target <= x_original.front()) {
        return y_original.front();
    }
    if (x_target >= x_original.back()) {
        return y_original.back();
    }

    // Find the interval [x_i, x_{i+1}] that contains x_target
    // Since x_original is sorted and equally spaced, we can optimize finding the interval
    // However, for a general interp1d, a loop or std::upper_bound is more robust.
    // Given the specific problem, we know x_original[i] = i.
    // So, floor(x_target) gives us the index i.
