    if (i >= x_original.size() - 1) i = x_original.size() - 2;


    double x0 = x_original[i];
    double x1 = x_original[i+1];
    double y0 = y_original[i];
    double y1 = y_original[i+1];

    // Linear interpolation formula
    return y0 + (y1 - y0) * (x_target - x0) / (x1 - x0);
