// Function to generate n equally spaced points between start and end (inclusive)
std::vector<double> linspace(double start, double end, int n) {
    std::vector<double> result(n);
    if (n <= 0) {
        return {};
    }
    if (n == 1) {
        result[0] = start;
        return result;
    }
    double step = (end - start) / (n - 1);
    for (int i = 0; i < n; ++i) {
        result[i] = start + i * step;
    }
    return result;
}

