  let finalResult = 'Initial';
  let currentRequestId = 0; // To track the latest request

  // Simulate an async function
  async function f(value) {
    console.log(`f(${value}) started`);
    return new Promise(resolve => {
      setTimeout(() => {
        console.log(`f(${value}) finished`);
        resolve(`Result for ${value}`);
      }, 1000 + Math.random() * 500); // Simulate variable delay
