      if (thisRequestId === currentRequestId) {
        finalResult = result;
      } else {
        console.log(`Ignoring stale result for request ID ${thisRequestId} (current: ${currentRequestId})`);
      }
    })();
  }

  // Example UI to change x
  function incrementX() {
    x++;
  }
</script>

<p>x: {x}</p>
<p>Final Result: {finalResult}</p>
<button on:click={incrementX}>Increment x</button>
```

**Explanation:**
- `currentRequestId` is incremented every time the reactive block runs (i.e., every time `x` changes).
