```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class moveCard : MonoBehaviour
{
    public storage Storage; // Assuming 'storage' is another script or a class holding game data
    public float speed = 20f;
    private float startTime;
    private float journeyLength;
    private Vector3 startPos; // Store the starting position as a Vector3
    private Quaternion startRot; // Store the starting rotation as a Quaternion
    public int dir = 1;
    private Vector3 endPos;
    private Coroutine currentMoveCoroutine; // To hold the reference to the running coroutine

    void Awake() {
        if (gameObject.name == "reference") {
            Storage.movePos = transform.position;
        }
    }

    public void moveToCenter() {
        // Stop any existing movement coroutine before starting a new one
        if (currentMoveCoroutine != null) {
            StopCoroutine(currentMoveCoroutine);
        }

        startPos = transform.position; // Capture the current position at the start
        startRot = transform.rotation; // Capture the current rotation at the start
        startTime = Time.time;

        endPos = new Vector3(Storage.movePos.x * dir, Storage.movePos.y, Storage.movePos.z);
        journeyLength = Vector3.Distance(startPos, endPos);

        // If start and end are the same, no need to move
        if (journeyLength <= 0.01f) { // Use a small epsilon for float comparison
            transform.position = endPos;
            transform.rotation = Quaternion.Euler(Storage.rot);
            Debug.Log("Already at target position.");
            return;
        }

        currentMoveCoroutine = StartCoroutine(MoveAnimation()); // Store the Coroutine reference
        Invoke("stopAnimation", 2f); // Consider if this Invoke is still needed or if the coroutine should naturally end
    }

    IEnumerator MoveAnimation() { // Renamed for clarity
        Debug.Log("Starting move coroutine. Target endPos: " + endPos);
        while(true) {
            float distanceCovered = (Time.time - startTime) * speed;
            float journeyAmount = distanceCovered / journeyLength;

            if (journeyAmount < 1f) {
                transform.position = Vector3.Lerp(startPos, endPos, journeyAmount);
                transform.rotation = Quaternion.Lerp(startRot, Quaternion.Euler(Storage.rot), journeyAmount);
                yield return null; // Wait for the next frame
            } else {
                // Ensure the object is exactly at the end position and rotation
                transform.position = endPos;
                transform.rotation = Quaternion.Euler(Storage.rot);
                Debug.Log("Coroutine finished naturally. Reached endPos: " + transform.position);
                currentMoveCoroutine = null; // Clear the reference
                yield break; // Exit the coroutine
            }
        }
    }

    private void stopAnimation() {
        Debug.Log("stopAnimation called. Coroutine ended prematurely?");
        if (currentMoveCoroutine != null) {
            StopCoroutine(currentMoveCoroutine);
            currentMoveCoroutine = null; // Clear the reference
            Debug.Log("Coroutine stopped by Invoke.");
        }
    }
}
```

**Explanation of Changes:**

