```kotlin
fun minimumPresses(word: String): Int {
    // Step 1: Count the frequency of each character
    val charFrequencies = IntArray(26) { 0 }
    for (char in word) {
        charFrequencies[char - 'a']++
    }

    // Step 2: Filter out characters that don't appear and sort frequencies in descending order
    val sortedFrequencies = charFrequencies.filter { it > 0 }.sortedDescending()

    // Step 3: Calculate the minimum pushes
    var totalPushes = 0
    for (i in sortedFrequencies.indices) {
        // There are 8 keys (2-9).
        // The first 8 most frequent characters get 1 push.
        // The next 8 most frequent characters get 2 pushes.
        // And so on.
        // The number of pushes for the i-th character (0-indexed) is (i / 8) + 1.
        val pushes = (i / 8) + 1
        totalPushes += sortedFrequencies[i] * pushes
    }

    return totalPushes
}

fun main() {
    println(minimumPresses("abcde")) // Output: 5
    println(minimumPresses("xyzxyzxyzxyz")) // Output: 12
    println(minimumPresses("aabbccddeeffgghhiiiiii")) // Output: 24
}
```

