  cluster_arn = var.create_ecs_cluster ? aws_ecs_cluster.this[0].arn : data.aws_ecs_cluster.existing[0].arn
  cluster_name = var.create_ecs_cluster ? aws_ecs_cluster.this[0].name : data.aws_ecs_cluster.existing[0].name
}

resource "aws_iam_role" "ecs_task_execution_role" {
  name = "${var.service_name}-ecs-task-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Action = "sts:AssumeRole",
      Effect = "Allow",
      Principal = {
        Service = "ecs-tasks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_policy" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_policy" "ssm_access_policy" {
  name        = "${var.service_name}-ssm-access-policy"
  description = "Allows ECS tasks to retrieve secrets from SSM Parameter Store"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = [
          "ssm:GetParameters",
          "ssm:GetParameter",
          "ssm:GetParametersByPath"
        ],
        Resource = var.cloudflare_token_ssm_arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_access_attachment" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = aws_iam_policy.ssm_access_policy.arn
}

resource "aws_ecs_task_definition" "warp_task" {
  family                   = "${var.service_name}-task"
  cpu                      = var.cpu
  memory                   = var.memory
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  execution_role_arn       = aws_iam_role.ecs_task_execution_role.arn
  task_role_arn            = aws_iam_role.ecs_task_execution_role.arn # Often the same as execution role for Fargate unless specific app permissions are needed

  container_definitions = jsonencode([
    {
      name      = "cloudflare-warp",
      image     = var.ecr_image_uri,
      essential = true,
      portMappings = [
        {
          containerPort = 2408, # Default WARP port
          hostPort      = 2408,
          protocol      = "udp"
        }
      ],
      secrets = [
        {
          name      = "WARP_TOKEN", # Environment variable name inside the container
          valueFrom = var.cloudflare_token_ssm_arn
        }
      ],
      logConfiguration = {
        logDriver = "awslogs",
        options = {
          "awslogs-group"         = "/ecs/${var.service_name}",
          "awslogs-region"        = data.aws_region.current.name,
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])
}

resource "aws_cloudwatch_log_group" "warp_log_group" {
  name              = "/ecs/${var.service_name}"
  retention_in_days = 7
}

resource "aws_ecs_service" "warp_service" {
  name            = var.service_name
  cluster         = local.cluster_name
  task_definition = aws_ecs_task_definition.warp_task.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = var.subnet_ids
    security_groups  = var.security_group_ids
    assign_public_ip = var.assign_public_ip
  }

  # Optional: Add a load balancer if needed
  # load_balancer {
  #   target_group_arn = aws_lb_target_group.warp.arn
  #   container_name   = "cloudflare-warp"
  #   container_port   = 2408
  # }

  depends_on = [
    aws_iam_role_policy_attachment.ecs_task_execution_policy,
    aws_iam_role_policy_attachment.ssm_access_attachment,
    aws_cloudwatch_log_group.warp_log_group
  ]
}

# CodePipeline for deployment
resource "aws_s3_bucket" "codepipeline_artifact_bucket" {
  bucket = "${var.service_name}-codepipeline-artifacts-${data.aws_caller_identity.current.account_id}"
  acl    = "private"
  versioning {
    enabled = true
  }
  tags = {
    Name = "${var.service_name}-codepipeline-artifacts"
  }
}

resource "aws_iam_role" "codepipeline_role" {
  name = "${var.service_name}-codepipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Action = "sts:AssumeRole",
      Effect = "Allow",
      Principal = {
        Service = "codepipeline.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "codepipeline_policy" {
  name = "${var.service_name}-codepipeline-policy"
  role = aws_iam_role.codepipeline_role.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:GetBucketVersioning"
        ],
        Resource = [
          aws_s3_bucket.codepipeline_artifact_bucket.arn,
          "${aws_s3_bucket.codepipeline_artifact_bucket.arn}/*"
        ]
      },
      {
        Effect   = "Allow",
        Action   = [
          "codebuild:BatchGetBuilds",
          "codebuild:StartBuild",
          "codebuild:StopBuild"
        ],
        Resource = aws_codebuild_project.ecs_deploy_project.arn
      },
      {
        Effect   = "Allow",
        Action   = [
          "ecs:DescribeServices",
          "ecs:UpdateService"
        ],
        Resource = aws_ecs_service.warp_service.arn
      },
      {
        Effect   = "Allow",
        Action   = [
          "iam:PassRole"
        ],
        Resource = [
          aws_iam_role.ecs_task_execution_role.arn,
          aws_iam_role.codepipeline_role.arn,
          aws_iam_role.codebuild_role.arn
        ],
        Condition = {
          "StringEqualsIfExists" = {
            "iam:PassedToService" = [
              "ecs-tasks.amazonaws.com",
              "codepipeline.amazonaws.com",
              "codebuild.amazonaws.com"
            ]
          }
        }
      },
      {
        Effect   = "Allow",
        Action   = [
          "ecr:DescribeImages"
        ],
        Resource = var.ecr_repo_arn
      }
    ]
  })
}

resource "aws_iam_role" "codebuild_role" {
  name = "${var.service_name}-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Action = "sts:AssumeRole",
      Effect = "Allow",
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name = "${var.service_name}-codebuild-policy"
  role = aws_iam_role.codebuild_role.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ],
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/${aws_codebuild_project.ecs_deploy_project.name}:*"
      },
      {
        Effect   = "Allow",
        Action   = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject"
        ],
        Resource = [
          aws_s3_bucket.codepipeline_artifact_bucket.arn,
          "${aws_s3_bucket.codepipeline_artifact_bucket.arn}/*"
        ]
      },
      {
        Effect   = "Allow",
        Action   = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability",
          "ecr:PutImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:GetAuthorizationToken"
        ],
        Resource = "*" # ECR permissions are often broad for CodeBuild to push/pull
      },
      {
        Effect   = "Allow",
        Action   = [
          "ecs:DescribeServices",
          "ecs:UpdateService"
        ],
        Resource = aws_ecs_service.warp_service.arn
      }
    ]
  })
}

resource "aws_codebuild_project" "ecs_deploy_project" {
  name          = "${var.service_name}-ecs-deploy"
  service_role  = aws_iam_role.codebuild_role.arn
  build_timeout = "5"

  artifacts {
    type = "CODEPIPELINE"
    # This project will output imagedefinitions.json for ECS deploy action
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:5.0"
    type                        = "LINUX_CONTAINER"
    privileged_mode             = true # Required for Docker commands
    environment_variable {
      name  = "AWS_ACCOUNT_ID"
      value = data.aws_caller_identity.current.account_id
    }
    environment_variable {
      name  = "AWS_DEFAULT_REGION"
      value = data.aws_region.current.name
    }
    environment_variable {
      name  = "ECS_CLUSTER_NAME"
      value = local.cluster_name
    }
    environment_variable {
      name  = "ECS_SERVICE_NAME"
      value = aws_ecs_service.warp_service.name
    }
    environment_variable {
      name  = "ECR_REPOSITORY_URI"
      value = var.ecr_image_uri # Full URI including repo and tag
    }
  }

  source {
    type = "CODEPIPELINE"
    buildspec = <<EOF
version: 0.2

phases:
  install:
    runtime-versions:
      docker: 19
  pre_build:
    commands:
      - echo "Logging in to Amazon ECR..."
      - aws ecr get-login-password --region $AWS_DEFAULT_REGION | docker login --username AWS --password-stdin $AWS_ACCOUNT_ID.dkr.ecr.$AWS_DEFAULT_REGION.amazonaws.com
  build:
    commands:
      - echo "Building the Docker image (if a Dockerfile is present in source artifact)..."
      # This buildspec assumes the source artifact contains a Dockerfile
      # If you're just deploying a pre-built image, this stage might be simpler
      - # docker build -t $ECR_REPOSITORY_URI .
      - # docker push $ECR_REPOSITORY_URI
      - echo "Generating imagedefinitions.json for ECS deployment..."
      - printf '[{"name":"cloudflare-warp","imageUri":"%s"}]' "$ECR_REPOSITORY_URI" > imagedefinitions.json
artifacts:
  files:
    - imagedefinitions.json
EOF
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "/aws/codebuild/${var.service_name}-ecs-deploy"
      stream_name = "codebuild-log-stream"
    }
  }
}

resource "aws_codepipeline" "ecs_pipeline" {
  name     = "${var.service_name}-pipeline"
  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    type     = "S3"
    location = aws_s3_bucket.codepipeline_artifact_bucket.bucket
  }

  stage {
    name = "Source"
    action {
      name             = "Source"
      category         = "Source"
      owner            = "AWS"
      provider         = var.codepipeline_source_provider
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = var.codepipeline_source_configuration
    }
  }

  stage {
    name = "BuildAndPrepareImage"
    action {
      name             = "BuildAndPrepareImage"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]
      version          = "1"

      configuration = {
        ProjectName = aws_codebuild_project.ecs_deploy_project.name
      }
    }
  }

  stage {
    name = "Deploy"
    action {
      name            = "DeployECS"
      category        = "Deploy"
      owner           = "AWS"
      provider        = "ECS"
      input_artifacts = ["build_output"]
      version         = "1"

      configuration = {
        ClusterName = local.cluster_name
        ServiceName = aws_ecs_service.warp_service.name
        FileName    = "imagedefinitions.json"
      }
    }
  }
}

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# variables.tf
variable "create_ecs_cluster" {
  description = "Whether to create a new ECS cluster. If false, an existing cluster name must be provided."
  type        = bool
  default     = true
}

variable "ecs_cluster_name" {
  description = "Name for the ECS cluster to create (if create_ecs_cluster is true)."
