The user wants a Swift iOS app called "Tennis Score Tracker" that tracks tennis scores for a match up to three sets. It should allow users to input scores and have an advanced option to track details of every point (winner, unforced error, forced error, ace, return winner, serve winner).

Here's a possible implementation using SwiftUI:

```swift
import SwiftUI

// MARK: - Data Models

// Enum for different types of point outcomes
enum PointOutcome: String, CaseIterable, Identifiable {
    var id: String { self.rawValue }

    case winner = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError = "Forced Error"
    case ace = "Ace"
    case returnWinner = "Return Winner"
    case serveWinner = "Serve Winner"
}

// Struct to store details of each point
struct PointDetail: Identifiable {
    let id = UUID()
    let player: String // "Player 1" or "Player 2"
    let outcome: PointOutcome? // Nil if advanced mode is off
    let timestamp: Date = Date()
}

// Enum for game point scores (0, 15, 30, 40, Advantage)
enum GamePoint: Int, CaseIterable {
    case zero = 0, fifteen = 1, thirty = 2, forty = 3, advantage = 4

    func displayString() -> String {
        switch self {
        case .zero: return "0"
        case .fifteen: return "15"
        case .thirty: return "30"
        case .forty: return "40"
        case .advantage: return "Ad"
        }
    }
}

// Struct for a single game's score
struct GameScore {
    var player1Points: Int = 0 // Raw points (0, 1, 2, 3, 4 for Ad)
    var player2Points: Int = 0

    mutating func reset() {
        player1Points = 0
        player2Points = 0
    }

    func displayScore() -> String {
        if player1Points >= 3 && player2Points >= 3 {
            if player1Points == player2Points {
                return "Deuce"
            } else if player1Points > player2Points {
                return "Ad P1"
            } else {
                return "Ad P2"
            }
        }

        let p1Display = GamePoint(rawValue: player1Points)?.displayString() ?? "0"
        let p2Display = GamePoint(rawValue: player2Points)?.displayString() ?? "0"
        return "\(p1Display) - \(p2Display)"
    }
}

// Struct for a single set's score
struct SetScore: Identifiable {
    let id = UUID()
    var player1Games: Int = 0
    var player2Games: Int = 0

    mutating func reset() {
        player1Games = 0
        player2Games = 0
    }
}

// ObservableObject to manage the entire match state
class TennisMatch: ObservableObject {
    @Published var sets: [SetScore] = [SetScore(), SetScore(), SetScore()] // Up to 3 sets
    @Published var currentSetIndex: Int = 0 // 0-indexed
    @Published var currentGame: GameScore = GameScore()
    @Published var detailedPoints: [PointDetail] = []
    @Published var advancedMode: Bool = false

    // Adds a point for the specified player, handling game and set logic
    func addPoint(forPlayer player: Int, outcome: PointOutcome? = nil) {
        // Record point detail if advanced mode is on or if an outcome is explicitly provided
        if advancedMode || outcome != nil {
            let playerString = (player == 1) ? "Player 1" : "Player 2"
            detailedPoints.append(PointDetail(player: playerString, outcome: outcome, timestamp: Date()))
        }

        // Update game points
        if player == 1 {
            updateGamePoints(forPlayer: &currentGame.player1Points, opponentPoints: &currentGame.player2Points)
        } else {
            updateGamePoints(forPlayer: &currentGame.player2Points, opponentPoints: &currentGame.player1Points)
        }

        // Check if game is won
        if isGameWon() {
            if player == 1 {
                sets[currentSetIndex].player1Games += 1
            } else {
                sets[currentSetIndex].player2Games += 1
            }
            currentGame.reset() // Reset game score for the next game

            // Check if set is won
            if isSetWon() {
                if currentSetIndex < sets.count - 1 {
                    currentSetIndex += 1 // Move to next set
                } else {
                    // Match is over (all sets played)
                    // In a real app, you'd handle match end, declare winner, etc.
                    print("Match Over!")
                }
            }
        }
    }

    private func updateGamePoints(forPlayer playerPoints: inout Int, opponentPoints: inout Int) {
        if playerPoints < 3 { // 0, 15, 30
            playerPoints += 1
        } else if playerPoints == 3 { // 40
            if opponentPoints < 3 { // Opponent has 0, 15, 30
                playerPoints += 1 // Player wins game
            } else if opponentPoints == 3 { // Deuce
                playerPoints += 1 // Player gets Advantage
            } else if opponentPoints == 4 { // Opponent has Advantage
                opponentPoints = 3 // Back to Deuce
            }
        } else if playerPoints == 4 { // Player has Advantage
            playerPoints += 1 // Player wins game
        }
    }

    private func isGameWon() -> Bool {
        let p1 = currentGame.player1Points
        let p2 = currentGame.player2Points

        // A player wins a game if they have at least 4 points and are ahead by at least 2 points.
        return (p1 >= 4 || p2 >= 4) && abs(p1 - p2) >= 2
    }

    private func isSetWon() -> Bool {
        let p1Games = sets[currentSetIndex].player1Games
        let p2Games = sets[currentSetIndex].player2Games

        // A player wins a set if they have at least 6 games and are ahead by at least 2 games.
        // (Tie-break rules would be more complex for 6-6, but simplified here)
        return (p1Games >= 6 || p2Games >= 6) && abs(p1Games - p2Games) >= 2
    }

