// Struct to represent the score within a single game
struct GameScore {
    var player1Points: Int = 0 // 0, 15, 30, 40, Ad
    var player2Points: Int = 0

    // Converts internal point representation to tennis display string
    func displayPoint(_ points: Int) -> String {
        switch points {
        case 0: return "0"
        case 1: return "15"
        case 2: return "30"
        case 3: return "40"
        case 4: return "Ad" // Advantage
        default: return ""
        }
    }

    // Returns the current game score as a string (e.g., "40-30", "Deuce", "Ad Player 1")
    func displayScore() -> String {
        if player1Points >= 3 && player2Points >= 3 {
            if player1Points == player2Points {
                return "Deuce"
            } else if player1Points == player2Points + 1 {
                return "Ad P1"
            } else if player2Points == player1Points + 1 {
                return "Ad P2"
            }
        }
        return "\(displayPoint(player1Points)) - \(displayPoint(player2Points))"
    }

    // Checks if the current game is over
    func isGameOver() -> Bool {
        let p1 = player1Points
        let p2 = player2Points

        // A player wins a game if they have at least 4 points and are at least 2 points ahead
        if (p1 >= 4 || p2 >= 4) && abs(p1 - p2) >= 2 {
            return true
        }
        return false
    }

    // Determines the winner of the current game, if any
    func gameWinner() -> String? {
        if isGameOver() {
            return player1Points > player2Points ? "Player 1" : "Player 2"
        }
        return nil
    }

    // Resets the game score to 0-0
    mutating func reset() {
        player1Points = 0
        player2Points = 0
    }
}

// Struct to represent the score within a single set
struct SetScore {
    var player1Games: Int = 0
    var player2Games: Int = 0

    // Checks if the current set is over
    func isSetOver() -> Bool {
        let p1 = player1Games
        let p2 = player2Games

        // A player wins a set if they have at least 6 games and are at least 2 games ahead
        // Special case for 7-6 tie-break (not implemented here, but common)
        if (p1 >= 6 || p2 >= 6) && abs(p1 - p2) >= 2 {
            return true
        }
        return false
    }

    // Determines the winner of the current set, if any
    func setWinner() -> String? {
        if isSetOver() {
            return player1Games > player2Games ? "Player 1" : "Player 2"
        }
        return nil
    }

    // Resets the set score to 0-0
    mutating func reset() {
        player1Games = 0
        player2Games = 0
    }
}

// ObservableObject to manage the entire match state
class TennisMatch: ObservableObject {
    @Published var currentSetIndex: Int = 0 // 0, 1, 2 for up to 3 sets
    @Published var sets: [SetScore] = [SetScore(), SetScore(), SetScore()]
    @Published var currentGame: GameScore = GameScore()
    @Published var pointDetails: [PointDetail] = [] // History of all points
    @Published var matchWinner: String? = nil

    // Adds a point for the specified player
    func addPoint(to player: String, outcome: PointOutcome? = nil) {
        guard matchWinner == nil else { return } // Don't add points if match is over

        // Record point detail if provided
        if let outcome = outcome {
            pointDetails.append(PointDetail(player: player, outcome: outcome, timestamp: Date()))
        } else {
            // If advanced details are off, default to a "Winner" for simplicity
            pointDetails.append(PointDetail(player: player, outcome: .winner, timestamp: Date()))
        }

        // Update game score
        if player == "Player 1" {
            updateGamePoints(forPlayer1: true)
        } else {
            updateGamePoints(forPlayer1: false)
        }

        // Check if game is over
        if currentGame.isGameOver() {
            if let winner = currentGame.gameWinner() {
                if winner == "Player 1" {
                    sets[currentSetIndex].player1Games += 1
                } else {
                    sets[currentSetIndex].player2Games += 1
                }
            }
            currentGame.reset() // Reset game score for the next game

            // Check if set is over
            if sets[currentSetIndex].isSetOver() {
                if let winner = sets[currentSetIndex].setWinner() {
                    // Move to next set or end match
                    if currentSetIndex < sets.count - 1 {
                        currentSetIndex += 1
                    } else {
                        // Match is over (best of 3 sets)
                        determineMatchWinner()
                    }
                }
            }
        }
    }

    // Logic to update game points based on tennis rules (0, 15, 30, 40, Ad, Deuce)
    private func updateGamePoints(forPlayer1: Bool) {
        if forPlayer1 {
            let p1 = currentGame.player1Points
            let p2 = currentGame.player2Points

            if p1 == 0 || p1 == 1 || p1 == 2 { // 0, 15, 30
                currentGame.player1Points += 1
            } else if p1 == 3 { // 40
                if p2 < 3 { // Opponent has 0, 15, 30 -> Player 1 wins game
                    currentGame.player1Points += 1 // Temporarily set to 4 for isGameOver check
                } else if p2 == 3 { // Deuce -> Player 1 gets Advantage
                    currentGame.player1Points += 1
                } else if p2 == 4 { // Opponent has Advantage -> Back to Deuce
                    currentGame.player2Points = 3
                }
            } else if p1 == 4 { // Player 1 has Advantage -> Player 1 wins game
                currentGame.player1Points += 1 // Temporarily set to 5 for isGameOver check
            }
        } else { // For Player 2
            let p1 = currentGame.player1Points
            let p2 = currentGame.player2Points

            if p2 == 0 || p2 == 1 || p2 == 2 { // 0, 15, 30
                currentGame.player2Points += 1
            } else if p2 == 3 { // 40
                if p1 < 3 { // Opponent has 0, 15, 30 -> Player 2 wins game
                    currentGame.player2Points += 1
                } else if p1 == 3 { // Deuce -> Player 2 gets Advantage
                    currentGame.player2Points += 1
                } else if p1 == 4 { // Opponent has Advantage -> Back to Deuce
                    currentGame.player1Points = 3
                }
            } else if p2 == 4 { // Player 2 has Advantage -> Player 2 wins game
                currentGame.player2Points += 1
            }
        }
    }

    // Determines the match winner based on sets won (best of 3)
    private func determineMatchWinner() {
        var p1SetsWon = 0
        var p2SetsWon = 0

        for set in sets {
            if set.isSetOver() {
                if set.player1Games > set.player2Games {
                    p1SetsWon += 1
                } else {
                    p2SetsWon += 1
                }
            }
        }

        if p1SetsWon >= 2 {
            matchWinner = "Player 1"
        } else if p2SetsWon >= 2 {
            matchWinner = "Player 2"
        }
    }

    // Resets the entire match
    func resetMatch() {
        currentSetIndex = 0
        sets = [SetScore(), SetScore(), SetScore()]
        currentGame.reset()
        pointDetails.removeAll()
        matchWinner = nil
    }
}

