// Define the Node structure
template <typename T>
struct Node {
    T data;
    std::unique_ptr<Node<T>> next; // Each node uniquely owns the next node

    // Constructor
    Node(T val) : data(val), next(nullptr) {}
};

// Define the LinkedList class
template <typename T>
class LinkedList {
private:
    std::unique_ptr<Node<T>> head; // The head of the list, uniquely owned by the list

public:
    // Constructor
    LinkedList() : head(nullptr) {}

    // Destructor is implicitly handled by unique_ptr.
    // When 'head' is destroyed, it destroys the first Node.
    // That Node's 'next' unique_ptr then destroys the second Node, and so on,
    // recursively cleaning up the entire list.

    // Function to add a new node to the front of the list
    void push_front(T val) {
        // Create a new node
        auto new_node = std::make_unique<Node<T>>(val);
        // The new node's 'next' now takes ownership of the current head
        new_node->next = std::move(head);
        // The list's 'head' now takes ownership of the new node
        head = std::move(new_node);
    }

    // Function to print the list
    void print() const {
        Node<T>* current = head.get(); // Get a raw pointer for traversal
        while (current != nullptr) {
            std::cout << current->data << " -> ";
            current = current->next.get(); // Move to the next node
        }
        std::cout << "nullptr" << std::endl;
    }

    // Optional: Function to remove the front node
    void pop_front() {
        if (head) { // Check if the list is not empty
            head = std::move(head->next); // Move ownership of the second node to head
        }
    }

    // Optional: Check if the list is empty
    bool is_empty() const {
        return head == nullptr;
    }
};

int main() {
