```java
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.security.web.util.matcher.RequestMatcher;

public class RefererHeaderRequestMatcher implements RequestMatcher {

    private final String refererValue;
    private final MatchType matchType;

    public enum MatchType {
        EQUALS, CONTAINS, STARTS_WITH, ENDS_WITH, REGEX
    }

    public RefererHeaderRequestMatcher(String refererValue, MatchType matchType) {
        this.refererValue = refererValue;
        this.matchType = matchType;
    }

    @Override
    public boolean matches(HttpServletRequest request) {
        String referer = request.getHeader("Referer");
        if (referer == null) {
            return false;
        }

        return switch (matchType) {
            case EQUALS -> referer.equals(refererValue);
            case CONTAINS -> referer.contains(refererValue);
            case STARTS_WITH -> referer.startsWith(refererValue);
            case ENDS_WITH -> referer.endsWith(refererValue);
            case REGEX -> referer.matches(refererValue);
        };
    }
}
```

**2. Define Multiple `SecurityFilterChain` Beans:**

Now, you can define multiple `SecurityFilterChain` beans, each configured with a specific `RefererHeaderRequestMatcher` and its own set of filters. The order of these beans matters; Spring Security will apply the first matching chain.

