import SwiftUI
import AVFoundation
import Combine

// MARK: - AudioRecorderViewModel
class AudioRecorderViewModel: NSObject, ObservableObject, AVAudioRecorderDelegate {
    @Published var isRecording = false
    @Published var audioPower: Float = 0.0 // Average power for the equalizer
    @Published var recordingURL: URL? // To store the URL of the last recording

    private var audioRecorder: AVAudioRecorder?
    private var meterTimer: Timer?
    private var cancellables = Set<AnyCancellable>()

    override init() {
        super.init()
        // Request permission when the view model is initialized
        requestMicrophonePermission()
    }

    deinit {
        stopRecording()
        meterTimer?.invalidate()
        cancellables.forEach { $0.cancel() }
    }

    private func requestMicrophonePermission() {
        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] granted in
            DispatchQueue.main.async {
                if !granted {
                    print("Microphone permission not granted.")
                    // Optionally, present an alert to the user
                }
            }
        }
    }

    func startRecording() {
        let audioSession = AVAudioSession.sharedInstance()

        do {
            try audioSession.setCategory(.playAndRecord, mode: .default, options: [.defaultToSpeaker])
            try audioSession.setActive(true, options: .notifyOthersOnDeactivation)

            let fileName = UUID().uuidString + ".m4a"
            let documentsDirectory = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            let fileURL = documentsDirectory.appendingPathComponent(fileName)
            self.recordingURL = fileURL // Store the URL

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44100,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue,
                AVEncoderBitRateKey: 128000,
            ]

            audioRecorder = try AVAudioRecorder(url: fileURL, settings: settings)
            audioRecorder?.delegate = self
            audioRecorder?.isMeteringEnabled = true
            audioRecorder?.prepareToRecord()
            audioRecorder?.record()

            isRecording = true
            startMetering()
            print("Recording started at: \(fileURL.lastPathComponent)")

        } catch {
            print("Failed to start recording: \(error.localizedDescription)")
            isRecording = false
        }
    }

    func stopRecording() {
        audioRecorder?.stop()
        isRecording = false
        stopMetering()

        do {
            try AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
        } catch {
            print("Failed to deactivate audio session: \(error.localizedDescription)")
        }
        print("Recording stopped.")
    }

    private func startMetering() {
        meterTimer = Timer.scheduledTimer(withTimeInterval: 0.1, repeats: true) { [weak self] _ in
            guard let self = self, let recorder = self.audioRecorder else { return }
            recorder.updateMeters()
            // Average power is typically between -160 dB (silence) and 0 dB (maximum amplitude)
            self.audioPower = recorder.averagePower(forChannel: 0)
        }
    }

    private func stopMetering() {
        meterTimer?.invalidate()
        meterTimer = nil
        audioPower = -160.0 // Reset power to silence when not recording
    }

    // MARK: - AVAudioRecorderDelegate
    func audioRecorderDidFinishRecording(_ recorder: AVAudioRecorder, successfully flag: Bool) {
        if flag {
            print("Audio recording finished successfully. File saved to: \(recorder.url.lastPathComponent)")
        } else {
            print("Audio recording failed or was interrupted.")
        }
        isRecording = false
        stopMetering()
    }

    func audioRecorderEncodeErrorDidOccur(_ recorder: AVAudioRecorder, error: Error?) {
        if let error = error {
            print("Audio Recorder Encode Error: \(error.localizedDescription)")
        }
        isRecording = false
        stopMetering()
    }
}

// MARK: - EqualizerView
struct EqualizerView: View {
    var audioPower: Float // dB value from -160 to 0
    var isRecording: Bool
    let numberOfBars = 10 // Number of bars in the equalizer

    // Normalize dB power to a 0-1 scale for UI, with a minimum height
    private func normalizedHeight(for power: Float) -> CGFloat {
        // Clamp power to a reasonable range, e.g., -50dB to 0dB for visual effect
        let clampedPower = max(-50.0, power)
        // Map -50dB to 0 and 0dB to 1
        let normalized = (clampedPower + 50) / 50
        // Ensure a minimum height even for very low power when recording
        return isRecording ? max(0.05, CGFloat(normalized)) : 0.0
    }

    var body: some View {
        HStack(alignment: .bottom, spacing: 3) {
            ForEach(0..<numberOfBars, id: \.self) { index in
                // Introduce slight variation for a more dynamic look
                let randomOffset = CGFloat.random(in: 0.8...1.2)
                let barHeight = normalizedHeight(for: audioPower) * 100 * randomOffset

                RoundedRectangle(cornerRadius: 2)
                    .fill(isRecording ? Color.blue : Color.gray.opacity(0.5))
                    .frame(width: 5, height: max(2, barHeight)) // Minimum height of 2 points
                    .animation(.easeInOut(duration: 0.1), value: barHeight)
            }
        }
        .frame(height: 100) // Fixed height for the equalizer container
    }
}

