   - Requests permissions on `onAppear`.

**Best Practices & Design Patterns:**
- **MVVM (Model-View-ViewModel):** Clearly separates concerns. `ContentView` (View) observes `AudioRecorderViewModel` (ViewModel), which encapsulates `AVFoundation` logic (Model interaction).
- **`@StateObject`:** Correctly manages the lifecycle of the `ViewModel` within the `View`.
- **`AVAudioSession`:** Proper setup for recording, including category and activation.
- **`AVAudioRecorder`:** Used for audio recording, with metering enabled for the equalizer.
- **File Management:** Saves recordings to the app's `Documents` directory for persistence.
- **Permissions:** Explicitly requests microphone permission.
- **Error Handling:** Basic `do-catch` blocks for `AVFoundation` operations.
- **UI Feedback:** Buttons are disabled/enabled based on recording state.
- **Equalizer Effect:** Uses `Timer` and `updateMeters()` to get real-time audio power, which is then mapped to visual bar heights. Randomness can be added for a more dynamic look.

```swift
import SwiftUI
import AVFoundation

// MARK: - ViewModel
final class AudioRecorderViewModel: NSObject, ObservableObject, AVAudioRecorderDelegate {
    @Published var isRecording = false
    @Published var powerLevels: [Float] = Array(repeating: 0, count: 5) // For 5 bars

    private var audioRecorder: AVAudioRecorder?
    private var levelTimer: Timer?
    private let numberOfBars = 5

    override init() {
        super.init()
    }

    func requestPermission() {
        AVAudioSession.sharedInstance().requestRecordPermission { granted in
            DispatchQueue.main.async {
                if !granted {
                    print("Microphone access denied.")
                    // Optionally, show an alert to the user
                }
            }
        }
    }

    func startRecording() {
        let session = AVAudioSession.sharedInstance()

        do {
            try session.setCategory(.playAndRecord, mode: .default, options: [.defaultToSpeaker])
            try session.setActive(true, options: .notifyOthersOnDeactivation)
        } catch {
            print("Failed to set up audio session: \(error.localizedDescription)")
            return
        }

        let url = getAudioFileURL()
        let settings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
            AVSampleRateKey: 44100,
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue,
            AVEncoderBitRateKey: 128000,
        ]

        do {
            audioRecorder = try AVAudioRecorder(url: url, settings: settings)
            audioRecorder?.delegate = self
            audioRecorder?.isMeteringEnabled = true
            audioRecorder?.prepareToRecord()
            audioRecorder?.record()
            isRecording = true
            startMetering()
            print("Recording started to: \(url.lastPathComponent)")
        } catch {
            print("Failed to start recording: \(error.localizedDescription)")
        }
    }

    func stopRecording() {
        audioRecorder?.stop()
        isRecording = false
        stopMetering()
        do {
            try AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
        } catch {
            print("Failed to deactivate audio session: \(error.localizedDescription)")
        }
    }

    private func getAudioFileURL() -> URL {
        let fileName = "recording_\(Date().timeIntervalSince1970).m4a"
        let documents = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        return documents.appendingPathComponent(fileName)
    }

    private func startMetering() {
        levelTimer = Timer.scheduledTimer(withTimeInterval: 0.05, repeats: true) { [weak self] _ in
            guard let self = self, let recorder = self.audioRecorder, recorder.isRecording else {
                return
            }
            recorder.updateMeters()

            // averagePower(forChannel: 0) gives value between ~-160 and 0 (dB)
            let averagePower = recorder.averagePower(forChannel: 0)

            // Normalize power from -60dB to 0dB to a 0.0 to 1.0 scale
            // Values below -60dB are considered silence for visual purposes
            let normalizedPower = max(0, (averagePower + 60) / 60) // Clamped to 0...1

            // Generate levels for each bar with some variation
            let newLevels = (0..<self.numberOfBars).map { _ in
                // Scale to a height (e.g., 0-100) and add a slight random factor for visual appeal
                Float(normalizedPower * 100) * Float.random(in: 0.8...1.2)
            }

            DispatchQueue.main.async {
                self.powerLevels = newLevels
            }
        }
    }

    private func stopMetering() {
        levelTimer?.invalidate()
        levelTimer = nil
        // Reset powerLevels so bars go down smoothly
        DispatchQueue.main.async {
            self.powerLevels = Array(repeating: 0, count: self.numberOfBars)
        }
    }

    // MARK: AVAudioRecorderDelegate
    func audioRecorderDidFinishRecording(_ recorder: AVAudioRecorder, successfully flag: Bool) {
        if flag {
            print("Successfully finished recording. File saved at: \(recorder.url.lastPathComponent)")
        } else {
            print("Recording failed or was interrupted.")
        }
        // Ensure UI state is reset even if recording stops unexpectedly
        DispatchQueue.main.async {
            self.isRecording = false
            self.stopMetering()
        }
    }

    func audioRecorderEncodeErrorDidOccur(_ recorder: AVAudioRecorder, error: Error?) {
        if let error = error {
            print("Audio Recorder Encode Error: \(error.localizedDescription)")
        }
        DispatchQueue.main.async {
            self.isRecording = false
            self.stopMetering()
        }
    }
}

// MARK: - Equalizer View Components
struct EqualizerBar: View {
    var power: Float // Expected 0...100
    var color: Color = .accentColor

    var body: some View {
        RoundedRectangle(cornerRadius: 2)
            .fill(color)
            .frame(width: 6, height: CGFloat(power).clamped(to: 2...100)) // Min height 2 for visibility
            .animation(.easeOut(duration: 0.05), value: power)
