}

struct EqualizerView: View {
    let levels: [Float]
    let maxHeight: CGFloat = 100

    var body: some View {
        HStack(spacing: 6) {
            ForEach(0..<levels.count, id: \.self) { index in
                EqualizerBar(power: levels[index])
            }
        }
        .frame(height: maxHeight, alignment: .bottom) // Align bars to the bottom
    }
}

// Helper extension for clamping values
extension Comparable {
    func clamped(to limits: ClosedRange<Self>) -> Self {
        return min(max(self, limits.lowerBound), limits.upperBound)
    }
}

// MARK: - Main View
struct ContentView: View {
    @StateObject private var recorderVM = AudioRecorderViewModel()

    var body: some View {
        VStack(spacing: 40) {
            Spacer()

            Text("Voice Recorder")
                .font(.largeTitle)
                .fontWeight(.bold)

            EqualizerView(levels: recorderVM.powerLevels)
                .padding()

            Spacer()

            HStack(spacing: 40) {
                Button(action: {
                    recorderVM.startRecording()
                }) {
                    Label("Start", systemImage: "mic.fill")
                        .font(.headline)
                        .padding()
                        .frame(minWidth: 140)
                        .background(recorderVM.isRecording ? Color.green.opacity(0.6) : Color.green)
                        .foregroundColor(.white)
                        .cornerRadius(10)
                }
