// supporting various numeric formats (decimal, hex, octal, binary)
// and numeric types (int, float).
bool parseCellValue(const QVariant &cellValue, int &result) {
    bool ok = false;

    // 1. Try to convert directly if it's already a numeric type
    if (cellValue.canConvert<double>()) {
        double d = cellValue.toDouble(&ok);
        if (ok) {
            int intVal = static_cast<int>(d);
            // Check if the double value is exactly an integer (e.g., 3.0 is 3, but 3.1 is not)
