                return true;
            }
        }
    }

    // 2. If not directly numeric or not an exact integer, try parsing as a string
    QString text = cellValue.toString().trimmed();
    if (text.isEmpty()) {
        return false;
    }

    // Try parsing as hexadecimal (0x prefix)
    if (text.startsWith("0x", Qt::CaseInsensitive)) {
        result = text.mid(2).toInt(&ok, 16);
        if (ok) return true;
    }
    // Try parsing as binary (0b prefix)
    else if (text.startsWith("0b", Qt::CaseInsensitive)) {
        // QVariant::toInt does not support binary directly, so manual parsing or QRegularExpression
        // For simplicity and robustness, let's use QRegularExpression for binary
        QRegularExpression binRe("^[01]+$");
        QString binPart = text.mid(2);
        if (binRe.match(binPart).hasMatch()) {
            result = 0;
            for (QChar c : binPart) {
                result = (result << 1) | (c.digitValue());
            }
            return true;
        }
    }
    // Try parsing as octal (0 prefix, but not 0x or 0b)
    else if (text.startsWith("0") && text.length() > 1) {
