#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <map> // Using map for component representatives, could also use unordered_map

// Disjoint Set Union (DSU) structure
struct DSU {
    std::vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1); // 1-based indexing
        std::iota(parent.begin(), parent.end(), 0); // parent[i] = i
    }

    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }

    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            parent[root_j] = root_i;
        }
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n, m;
    std::cin >> n >> m;

    std::vector<long long> prices(n + 1); // 1-based indexing for prices
    for (int i = 1; i <= n; ++i) {
        std::cin >> prices[i];
    }

    DSU dsu(n);

    // Process existing roads
    for (int k = 0; k < m; ++k) {
        int u, v;
        std::cin >> u >> v;
        dsu.unite(u, v);
    }

    // Find the cheapest house in each connected component
    // map: component_root -> {min_price_in_component, house_id_with_min_price}
    std::map<int, std::pair<long long, int>> component_cheapest_house;

    for (int i = 1; i <= n; ++i) {
        int root = dsu.find(i);
        if (component_cheapest_house.find(root) == component_cheapest_house.end()) {
            component_cheapest_house[root] = {prices[i], i};
        } else {
            if (prices[i] < component_cheapest_house[root].first) {
                component_cheapest_house[root] = {prices[i], i};
            }
        }
    }

    // If there's only one component, no new roads are needed
    if (component_cheapest_house.size() <= 1) {
        std::cout << 0 << std::endl;
        return 0;
    }

    // Find the overall cheapest house among all components
    long long global_min_price = -1;
    int global_min_house_id = -1;
    int global_min_house_root = -1;

    for (auto const& [root, info] : component_cheapest_house) {
        if (global_min_house_id == -1 || info.first < global_min_price) {
            global_min_price = info.first;
            global_min_house_id = info.second;
            global_min_house_root = root;
        }
    }

    // Build roads to connect all other components to the component of global_min_house
    std::vector<std::pair<int, int>> new_roads;
    for (auto const& [root, info] : component_cheapest_house) {
        if (root != global_min_house_root) { // Don't connect a component to itself
            new_roads.push_back({global_min_house_id, info.second});
        }
    }

    std::cout << new_roads.size() << std::endl;
    for (const auto& road : new_roads) {
        std::cout << road.first << " " << road.second << std::endl;
    }

    return 0;
}

