        DetectSurface();
        ApplyRotation();
        HandleMovement();
        ApplySurfaceGravity();
    }

    private void DetectSurface()
    {
        // Raycast downwards from the character's current position
        // Use transform.position + transform.up * 0.1f to avoid self-collision if character origin is exactly on surface
