            // If no surface detected, assume default world gravity and no specific surface normal
            currentSurfaceNormal = Vector3.up;
            isGrounded = false;
        }
    }

    private void ApplyRotation()
    {
        // Calculate the target rotation to align character's up with the surface normal
        Quaternion targetRotation = Quaternion.FromToRotation(transform.up, currentSurfaceNormal) * transform.rotation;
        // Smoothly interpolate to the target rotation
        transform.rotation = Quaternion.Slerp(transform.rotation, targetRotation, rotationSpeed * Time.deltaTime);
    }

    private void HandleMovement()
