    public float gravityForce = 20f;  // Force to keep character grounded
    public float raycastDistance = 1.5f; // How far down to raycast for the surface
    public float groundCheckOffset = 0.1f; // Offset for raycast origin to avoid self-intersection

    private CharacterController controller;
    private Vector3 currentSurfaceNormal = Vector3.up; // Default to world up
    private Vector3 verticalVelocity = Vector3.zero;

    void Start()
    {
        controller = GetComponent<CharacterController>();
    }

    void Update()
    {
        // 1. Raycast to detect the surface and its normal
        RaycastHit hit;
        // Raycast slightly above the character's base to prevent hitting its own collider
        Vector3 rayOrigin = transform.position + transform.up * groundCheckOffset;

        if (Physics.Raycast(rayOrigin, -transform.up, out hit, raycastDistance))
        {
            currentSurfaceNormal = hit.normal;

            // 2. Align character's up vector with the surface normal
            // Calculate the target rotation: FromToRotation finds the rotation from current up to target normal
            Quaternion targetRotation = Quaternion.FromToRotation(transform.up, currentSurfaceNormal) * transform.rotation;
            transform.rotation = Quaternion.Slerp(transform.rotation, targetRotation, rotationSpeed * Time.deltaTime);

            // 3. Handle player input and project movement onto the surface
            float horizontalInput = Input.GetAxis("Horizontal");
            float verticalInput = Input.GetAxis("Vertical");

            Vector3 inputDirection = new Vector3(horizontalInput, 0, verticalInput).normalized;

            // Convert input from local character space to world space relative to character's forward/right
            // This ensures 'forward' is always along the character's local forward on the surface
            Vector3 worldInputDirection = transform.TransformDirection(inputDirection);

            // Project the world input direction onto the plane defined by the surface normal
            Vector3 moveDirection = Vector3.ProjectOnPlane(worldInputDirection, currentSurfaceNormal).normalized;

            // Apply movement
            Vector3 movement = moveDirection * moveSpeed;

            // 4. Apply custom gravity/grounding force
            // Reset vertical velocity if grounded
            if (controller.isGrounded)
            {
                verticalVelocity = Vector3.zero;
            }
            // Apply gravity along the surface normal
            verticalVelocity += -currentSurfaceNormal * gravityForce * Time.deltaTime;

            // Combine movement and vertical velocity
            controller.Move((movement + verticalVelocity) * Time.deltaTime);
        }
        else
        {
            // If no surface is detected, apply standard world gravity
            currentSurfaceNormal = Vector3.up; // Revert to default up
            verticalVelocity += Physics.gravity * Time.deltaTime;
            controller.Move(verticalVelocity * Time.deltaTime);
        }
    }
}
