```cpp
#include <atomic>
#include <iostream>
#include <thread>
#include <vector>

// Function to atomically increment i if i < x
void increment_if_less(std::atomic<int>& i, const std::atomic<int>& x) {
    int current_i_val;
    int current_x_val;

    do {
        current_i_val = i.load(std::memory_order_relaxed); // Load i's current value
        current_x_val = x.load(std::memory_order_acquire); // Load x's current value

        // If i is already >= x, we don't need to increment.
        // Break the loop and return.
        if (current_i_val >= current_x_val) {
            return;
        }

        // Attempt to increment i.
        // If i's value is still current_i_val, it will be updated to current_i_val + 1.
        // If i's value has changed, current_i_val will be updated with the new value of i,
        // and the loop will retry.
    } while (!i.compare_exchange_weak(current_i_val, current_i_val + 1,
                                      std::memory_order_release,
                                      std::memory_order_relaxed));

    // If the loop completes, i was successfully incremented.
    // std::cout << "Thread " << std::this_thread::get_id() << ": i incremented to " << current_i_val + 1 << std::endl;
}

int main() {
