    x.store(8); // Atomically change the boundary
    i.store(5); // Reset i for demonstration

    threads.clear();
    for (int t = 0; t < 10; ++t) {
        threads.emplace_back(increment_if_less, std::ref(i), std::ref(x));
    }

    for (auto& th : threads) {
        th.join();
    }

    std::cout << "Final i: " << i.load() << std::endl;

    return 0;
}
```

