```typescript
type Result<T, E = Error> =
  | { success: true; value: T }
  | { success: false; error: E };

function wrapFunction<T, Args extends any[], E = Error>(
  func: (...args: Args) => T
): (...args: Args) => Result<T, E> {
  return (...args: Args): Result<T, E> => {
    try {
      const value = func(...args);
      return { success: true, value };
    } catch (error: unknown) {
      return { success: false, error: error as E };
    }
  };
}

// Example usage:

function mightThrow(a: number, b: number): number {
  if (b === 0) {
    throw new Error("Cannot divide by zero");
  }
  return a / b;
}

const safeMightThrow = wrapFunction(mightThrow);

const result1 = safeMightThrow(10, 2);
if (result1.success) {
  console.log("Success:", result1.value); // Success: 5
} else {
  console.error("Error:", result1.error.message);
}

const result2 = safeMightThrow(10, 0);
if (result2.success) {
  console.log("Success:", result2.value);
} else {
  console.error("Error:", result2.error.message); // Error: Cannot divide by zero
}

// Async version
type AsyncResult<T, E = Error> =
  | { success: true; value: T }
  | { success: false; error: E };

function wrapAsyncFunction<T, Args extends any[], E = Error>(
  func: (...args: Args) => Promise<T>
): (...args: Args) => Promise<AsyncResult<T, E>> {
  return async (...args: Args): Promise<AsyncResult<T, E>> => {
    try {
      const value = await func(...args);
      return { success: true, value };
    } catch (error: unknown) {
      return { success: false, error: error as E };
    }
  };
}

// Example async usage:
async function mightThrowAsync(a: number, b: number): Promise<number> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (b === 0) {
        reject(new Error("Cannot divide by zero asynchronously"));
      } else {
        resolve(a / b);
      }
    }, 100);
  });
}

const safeMightThrowAsync = wrapAsyncFunction(mightThrowAsync);

(async () => {
  const asyncResult1 = await safeMightThrowAsync(20, 4);
  if (asyncResult1.success) {
    console.log("Async Success:", asyncResult1.value); // Async Success: 5
  } else {
    console.error("Async Error:", asyncResult1.error.message);
  }

  const asyncResult2 = await safeMightThrowAsync(20, 0);
  if (asyncResult2.success) {
    console.log("Async Success:", asyncResult2.value);
  } else {
    console.error("Async Error:", asyncResult2.error.message); // Async Error: Cannot divide by zero asynchronously
  }
})();
```

