using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public static class CustomHashSetStringMarshaller
{
    /// <summary>
    /// Marshals a HashSet<string> instance into a byte array using a custom binary format.
    /// Format:
    /// - 4 bytes: Count of elements (int)
    /// - For each string:
    ///   - 4 bytes: Length of the UTF-8 encoded string in bytes (int)
    ///   - N bytes: UTF-8 encoded string content
    /// </summary>
    public static byte[] MarshalHashSet(HashSet<string> hashSet)
    {
        if (hashSet == null)
        {
            throw new ArgumentNullException(nameof(hashSet));
        }

        using (var ms = new MemoryStream())
        using (var writer = new BinaryWriter(ms, Encoding.UTF8, leaveOpen: true))
        {
            // Write the count of elements
            writer.Write(hashSet.Count);

            // Write each string
            foreach (var str in hashSet)
            {
                if (str == null)
                {
                    // Decide how to handle null strings. For simplicity, we'll throw.
                    // Alternatively, you could write a special marker (e.g., -1 for length).
                    throw new InvalidOperationException("HashSet contains a null string, which cannot be marshalled with this method.");
                }

                // Get UTF-8 bytes for the string
                byte[] stringBytes = Encoding.UTF8.GetBytes(str);

