            }

            // 2. Read each string
            for (int i = 0; i < count; i++)
            {
                int stringLength;
                try
                {
                    stringLength = reader.ReadInt32();
                }
                catch (EndOfStreamException)
                {
                    throw new ArgumentException($"Invalid data format: Unable to read string length for element {i}.", nameof(data));
                }

                if (stringLength < 0)
                {
                    throw new ArgumentException($"Invalid data format: Negative string length encountered for element {i}.", nameof(data));
                }

                byte[] stringBytes;
                try
                {
                    stringBytes = reader.ReadBytes(stringLength);
                }
                catch (EndOfStreamException)
                {
