 *
 * @param string $orderCreatedDate The initial order creation date string (e.g., "25/06/2024 10:45 AM").
 * @param array $processes An array of process definitions. Each process must have 'completed_days'.
 * @return array The updated processes array with 'start_date' and 'end_date' calculated.
 */
function calculateProcessDates(string $orderCreatedDate, array $processes): array
{
    // Define the expected date format
    $dateFormat = 'd/m/Y h:i A';

    // Initialize the current start date with the order created date
    // Use a Carbon instance for easy date manipulation
    $currentStartDate = Carbon::createFromFormat($dateFormat, $orderCreatedDate);

