<?php

namespace Drupal\my_module\Plugin\Block;

use Drupal\Core\Block\BlockBase;
use Drupal\Core\Entity\EntityTypeManagerInterface;
use Drupal\Core\Plugin\ContainerFactoryPluginInterface;
use Symfony\Component\DependencyInjection\ContainerInterface;

/**
 * Provides a 'Article Teaser List by Tag' Block.
 *
 * @Block(
 *   id = "article_teaser_list_by_tag_block",
 *   admin_label = @Translation("Article Teaser List by Tag 'foobar'"),
 *   category = @Translation("Custom"),
 * )
 */
class ArticleTeaserListByTagBlock extends BlockBase implements ContainerFactoryPluginInterface {

  /**
   * The entity type manager.
   *
   * @var \Drupal\Core\Entity\EntityTypeManagerInterface
   */
  protected $entityTypeManager;

  /**
   * Constructs a new ArticleTeaserListByTagBlock instance.
   *
   * @param array $configuration
   *   A configuration array containing information about the plugin instance.
   * @param string $plugin_id
   *   The plugin_id for the plugin instance.
   * @param mixed $plugin_definition
   *   The plugin implementation definition.
   * @param \Drupal\Core\Entity\EntityTypeManagerInterface $entity_type_manager
   *   The entity type manager service.
   */
  public function __construct(array $configuration, $plugin_id, $plugin_definition, EntityTypeManagerInterface $entity_type_manager) {
    parent::__construct($configuration, $plugin_id, $plugin_definition);
    $this->entityTypeManager = $entity_type_manager;
  }

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container, array $configuration, $plugin_id, $plugin_definition) {
    return new static(
      $configuration,
      $plugin_id,
      $plugin_definition,
      $container->get('entity_type.manager')
    );
  }

  /**
   * {@inheritdoc}
   */
  public function build() {
    $term_name = 'foobar';
    $vocabulary_id = 'tags'; // Assuming 'tags' is the machine name of your taxonomy vocabulary.
    $field_name = 'field_tags'; // Assuming 'field_tags' is the machine name of your taxonomy reference field on the article content type.

    // 1. Load the taxonomy term 'foobar'.
    $term_storage = $this->entityTypeManager->getStorage('taxonomy_term');
    $terms = $term_storage->loadByProperties([
      'name' => $term_name,
      'vid' => $vocabulary_id,
    ]);

    if (empty($terms)) {
      return [
        '#markup' => $this->t('No articles found with the tag "@tag".', ['@tag' => $term_name]),
        '#cache' => [
          'tags' => ['taxonomy_term_list'], // Cache tag for taxonomy term list.
        ],
      ];
    }

    /** @var \Drupal\taxonomy\TermInterface $term */
    $term = reset($terms);
    $term_id = $term->id();

    // 2. Build an entity query to get published article nodes tagged with 'foobar'.
    $node_storage = $this->entityTypeManager->getStorage('node');
    $query = $node_storage->getQuery()
      ->condition('type', 'article')
      ->condition('status', 1)
      ->condition($field_name . '.target_id', $term_id)
      ->sort('created', 'DESC')
      ->range(0, 5); // Limit to 5 articles for a teaser list.

    $nids = $query->execute();

    if (empty($nids)) {
      return [
        '#markup' => $this->t('No articles found with the tag "@tag".', ['@tag' => $term_name]),
        '#cache' => [
          'tags' => ['node_list', 'taxonomy_term:' . $term_id],
        ],
      ];
    }

    // 3. Load the nodes.
    $nodes = $node_storage->loadMultiple($nids);

    // 4. Render each node in 'teaser' view mode.
    $view_builder = $this->entityTypeManager->getViewBuilder('node');
    $rendered_teasers = [];
    foreach ($nodes as $node) {
      $rendered_teasers[] = $view_builder->view($node, 'teaser');
    }

    // 5. Wrap the rendered teasers with Bootstrap 5 list group styling.
    // We'll use a custom Twig template for better control over Bootstrap markup.
    return [
      '#theme' => 'my_module_article_teaser_list',
      '#items' => $rendered_teasers,
      '#cache' => [
        'tags' => ['node_list', 'taxonomy_term:' . $term_id],
        'contexts' => ['url.path'], // If the block content might vary by URL.
      ],
    ];
  }

}
