   */
  public function __construct(array $configuration, $plugin_id, $plugin_definition, EntityTypeManagerInterface $entity_type_manager) {
    parent::__construct($configuration, $plugin_id, $plugin_definition);
    $this->entityTypeManager = $entity_type_manager;
  }

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container, array $configuration, $plugin_id, $plugin_definition) {
    return new static(
      $configuration,
      $plugin_id,
      $plugin_definition,
      $container->get('entity_type.manager')
    );
  }

  /**
   * {@inheritdoc}
   */
  public function build() {
    $term_name = 'foobar';
    $vocabulary_id = 'tags'; // Assuming 'tags' is the machine name of your vocabulary.
    $article_content_type = 'article';
    $taxonomy_field_name = 'field_tags'; // Assuming 'field_tags' is the machine name of your taxonomy reference field on the article content type.

    // 1. Load the taxonomy term 'foobar'.
    $term_storage = $this->entityTypeManager->getStorage('taxonomy_term');
    $terms = $term_storage->loadByProperties([
      'name' => $term_name,
      'vid' => $vocabulary_id,
    ]);

    if (empty($terms)) {
      return [
        '#markup' => $this->t('No taxonomy term "@term" found in vocabulary "@vocab".', [
          '@term' => $term_name,
          '@vocab' => $vocabulary_id,
        ]),
        '#cache' => [
          'tags' => ['taxonomy_term_list'], // Cache tag for all taxonomy terms.
        ],
      ];
    }

    /** @var \Drupal\taxonomy\TermInterface $term */
    $term = reset($terms);
    $term_id = $term->id();

    // 2. Craft the Entity Query to find article nodes tagged with 'foobar'.
    $node_storage = $this->entityTypeManager->getStorage('node');
    $query = $node_storage->getQuery()
      ->condition('status', 1) // Only published nodes.
      ->condition('type', $article_content_type) // Only 'article' content type.
      ->condition($taxonomy_field_name . '.target_id', $term_id) // Filter by the taxonomy term ID.
      ->sort('created', 'DESC') // Order by creation date, newest first.
      ->range(0, 5); // Limit to 5 articles for a teaser list.

    $nids = $query->execute();

    if (empty($nids)) {
      return [
        '#markup' => $this->t('No articles found tagged with "@term".', ['@term' => $term_name]),
        '#cache' => [
          'tags' => ['node_list'], // Cache tag for all nodes.
          'contexts' => ['url.path'], // If the block might appear on different paths.
        ],
      ];
    }

    // 3. Load the nodes and prepare them for rendering.
    $nodes = $node_storage->loadMultiple($nids);
    $view_builder = $this->entityTypeManager->getViewBuilder('node');

    $items = [];
    foreach ($nodes as $node) {
      $items[] = $view_builder->view($node, 'teaser');
    }

    // 4. Incorporate basic Bootstrap 5 styles.
    // Using #theme 'item_list' is a good way to get a basic list structure.
    // We can add Bootstrap classes to the ul and li elements.
    $build = [
      '#theme' => 'item_list',
      '#items' => $items,
      '#attributes' => [
        'class' => ['list-group'], // Bootstrap 5 class for the ul element.
      ],
      '#item_attributes' => [
        'class' => ['list-group-item'], // Bootstrap 5 class for each li element.
      ],
      '#cache' => [
        'tags' => $this->getCacheTags($nids, $term_id),
        'contexts' => ['user.permissions'], // If access to nodes depends on user permissions.
      ],
    ];

    return $build;
  }

  /**
   * Helper to get cache tags for the block.
   *
   * @param array $nids
   *   An array of node IDs.
   * @param int $term_id
   *   The taxonomy term ID.
   *
   * @return array
   *   An array of cache tags.
   */
  protected function getCacheTags(array $nids, int $term_id) {
    $tags = ['node_list', 'taxonomy_term:' . $term_id];
    foreach ($nids as $nid) {
      $tags[] = 'node:' . $nid;
    }
    return $tags;
  }

}
