use std::{io, time::Duration};
use std::os::unix::io::AsRawFd;
use libc::{timeval, setsockopt, getsockopt, SOL_SOCKET, SO_RCVTIMEO};

// Helper to convert Duration to timeval
fn duration_to_timeval(dur: Duration) -> timeval {
    timeval {
        tv_sec: dur.as_secs() as _,
        tv_usec: dur.subsec_micros() as _,
    }
}

// Helper to convert timeval to Duration
fn timeval_to_duration(tv: timeval) -> Duration {
    Duration::new(tv.tv_sec as u64, tv.tv_usec as u32 * 1000)
}

trait SockOpt {
    fn set_read_timeout(&self, duration: Option<Duration>) -> io::Result<()>;
    fn read_timeout(&self) -> io::Result<Option<Duration>>;
}

impl SockOpt for tokio::net::UdpSocket {
    fn set_read_timeout(&self, duration: Option<Duration>) -> io::Result<()> {
        let fd = self.as_raw_fd();
        let mut tv = duration.map(duration_to_timeval).unwrap_or_else(|| timeval { tv_sec: 0, tv_usec: 0 }); // Use 0,0 for no timeout or specific value
