RTC_DS3231 rtc;

// --- Pin Definitions ---
const int LIVING_ROOM_LIGHT_PIN = 3; // PWM
const int LIVING_ROOM_TV_PIN    = 5; // PWM
const int BEDROOM_LIGHT_PIN     = 6; // PWM
const int BEDROOM_TV_PIN        = 9; // PWM
const int NIGHT_MODE_TOGGLE_PIN = 2; // Digital input for night mode (pull-up)

// --- Time Acceleration Settings ---
float timeAccelerationRatio = 6.0; // Default 6:1
unsigned long realMillisAtModelMidnight = 0; // Stores millis() when model time was last 00:00

// --- Night Mode Setting ---
bool nightModeFullDuration = true; // true = 2 hours, false = 1 hour for bedroom night TV

// --- TV Flicker Variables ---
unsigned long lastFlickerMillis[2] = {0, 0}; // For LR TV and BR TV
int flickerBrightness[2] = {0, 0};
const int FLICKER_INTERVAL = 50; // ms between flicker updates

// --- Function Prototypes ---
void setAllLightsOff();
void updateOLED(int modelHour, int modelMinute, const char* eventName);
void tvFlicker(int tvPin, int tvIndex); // tvIndex 0 for LR, 1 for BR

void setup() {
  Serial.begin(9600);

  // Initialize pins
  pinMode(LIVING_ROOM_LIGHT_PIN, OUTPUT);
  pinMode(LIVING_ROOM_TV_PIN, OUTPUT);
  pinMode(BEDROOM_LIGHT_PIN, OUTPUT);
  pinMode(BEDROOM_TV_PIN, OUTPUT);
  pinMode(NIGHT_MODE_TOGGLE_PIN, INPUT_PULLUP); // Use internal pull-up

  setAllLightsOff(); // Ensure all lights are off initially

  // Initialize RTC
  if (!rtc.begin()) {
    Serial.println("Couldn't find RTC");
    while (1); // Halt if RTC not found
  }
  if (rtc.lostPower()) {
    Serial.println("RTC lost power, setting to compile time");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }

  // Initialize OLED
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { // Check your OLED I2C address
    Serial.println(F("SSD1306 allocation failed"));
    for (;;); // Halt if OLED not found
  }
  display.clearDisplay();
  display.display();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0,0);
  display.println("Initializing...");
  display.display();

  // Set initial realMillisAtModelMidnight based on current RTC time
  DateTime now = rtc.now();
  // Calculate how many real milliseconds have passed since the last model midnight
  // This assumes the RTC is set to a reasonable real-world time.
  // We want model time 00:00 to align with some real time.
  // For simplicity, let's assume model 00:00 aligns with real 00:00 of the current day.
  // This means `realMillisAtModelMidnight` is `millis()` when the RTC was last 00:00:00.
  // A more robust approach would be to store a `realTimeReference` (DateTime) and calculate from there.
  // For now, let's just use `millis()` as a relative timer.
  // The prompt implies the simulation starts and continues, so `millis()` is fine for elapsed time.
  // We need a fixed point in real time that corresponds to model 00:00.
  // Let's say the simulation starts at real 00:00:00, and that's model 00:00:00.
  // Or, more practically, when the Arduino starts, whatever the real time is, that's our reference point for model 00:00.
  // Let's simplify: `realMillisAtModelMidnight` is `millis()` when the *current model day* started.
  // This will be updated every time the model day rolls over.
  realMillisAtModelMidnight = millis(); // For now, assume current real time is model 00:00
                                        // This will be corrected in loop()
}

void loop() {
  // Read night mode toggle
  // LOW means button pressed (night mode OFF, 1 hour duration)
  nightModeFullDuration = (digitalRead(NIGHT_MODE_TOGGLE_PIN) == HIGH);

  // --- Calculate Model Time ---
  unsigned long currentRealMillis = millis();
  unsigned long elapsedRealMillis = currentRealMillis - realMillisAtModelMidnight;

  // Convert elapsed real milliseconds to model milliseconds
  unsigned long elapsedModelMillis = (unsigned long)(elapsedRealMillis * timeAccelerationRatio);

  // Total model seconds in a day = 24 * 60 * 60 = 86400
  // Total model milliseconds in a day = 86400 * 1000 = 86,400,000
  const unsigned long MODEL_MILLIS_IN_DAY = 86400000UL;

  // If model time has rolled over to the next day, reset realMillisAtModelMidnight
  if (elapsedModelMillis >= MODEL_MILLIS_IN_DAY) {
    realMillisAtModelMidnight += (MODEL_MILLIS_IN_DAY / timeAccelerationRatio); // Advance reference by one model day's worth of real time
    elapsedModelMillis %= MODEL_MILLIS_IN_DAY; // Keep model time within current day
  }

  int modelHour = (elapsedModelMillis / (1000UL * 3600UL)) % 24;
  int modelMinute = (elapsedModelMillis / (1000UL * 60UL)) % 60;
  int modelTotalMinutes = modelHour * 60 + modelMinute;

  // --- Event Handling ---
  const char* currentEvent = "Idle";
  setAllLightsOff(); // Start with all lights off, then turn on as needed

  // Bedroom Morning News TV (07:00 - 08:00)
  if (modelTotalMinutes >= (7 * 60) && modelTotalMinutes < (8 * 60)) {
    currentEvent = "BR TV Morning";
    tvFlicker(BEDROOM_TV_PIN, 1);
  }

  // Bedroom Lights ON (07:00 - 09:00)
  if (modelTotalMinutes >= (7 * 60) && modelTotalMinutes < (9 * 60)) {
    analogWrite(BEDROOM_LIGHT_PIN, 255);
    currentEvent = "BR Lights ON"; // Prioritize TV event if both active
  }

  // Living Room Lights ON (18:00 - 22:00)
  if (modelTotalMinutes >= (18 * 60) && modelTotalMinutes < (22 * 60)) {
    analogWrite(LIVING_ROOM_LIGHT_PIN, 255);
    currentEvent = "LR Lights ON"; // Prioritize TV event if both active
  }

  // Living Room Evening TV (18:00 - 22:00)
  if (modelTotalMinutes >= (18 * 60) && modelTotalMinutes < (22 * 60)) {
    currentEvent = "LR TV Evening";
    tvFlicker(LIVING_ROOM_TV_PIN, 0);
  }

  // Bedroom Night TV (22:00 - 00:00 or 22:00 - 23:00)
  int nightTvEndMinute = nightModeFullDuration ? (24 * 60) : (23 * 60); // 00:00 or 23:00
  if (modelTotalMinutes >= (22 * 60) && modelTotalMinutes < nightTvEndMinute) {
    currentEvent = "BR TV Night";
    tvFlicker(BEDROOM_TV_PIN, 1);
  }

  // --- Update OLED Display ---
  updateOLED(modelHour, modelMinute, currentEvent);

  // Small delay to prevent busy-waiting and allow other tasks (like flicker)
  delay(100);
}

void setAllLightsOff() {
  analogWrite(LIVING_ROOM_LIGHT_PIN, 0);
  analogWrite(LIVING_ROOM_TV_PIN, 0);
  analogWrite(BEDROOM_LIGHT_PIN, 0);
  analogWrite(BEDROOM_TV_PIN, 0);
}

void tvFlicker(int tvPin, int tvIndex) {
  if (millis() - lastFlickerMillis[tvIndex] > FLICKER_INTERVAL) {
    flickerBrightness[tvIndex] = random(50, 200); // Adjust range for desired flicker effect
    analogWrite(tvPin, flickerBrightness[tvIndex]);
    lastFlickerMillis[tvIndex] = millis();
  }
}

void updateOLED(int hour, int minute, const char* eventName) {
  display.clearDisplay();
  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);

  char timeStr[6]; // HH:MM\0
  sprintf(timeStr, "%02d:%02d", hour, minute);
  display.setCursor(0, 0);
  display.print(timeStr);

  display.setTextSize(1);
  display.setCursor(0, 20);
  display.print("Event:");
  display.setCursor(0, 30);
  display.print(eventName);

  display.setCursor(0, 45);
  display.print("Ratio: ");
  display.print(timeAccelerationRatio, 1); // 1 decimal place

  display.setCursor(0, 55);
  display.print("Night Mode: ");
  display.print(nightModeFullDuration ? "2hr" : "1hr");

  display.display();
}
```

**Critique of Assistant A's Answer**

1.  **Correctness and Accuracy**:
    *   **Time Acceleration**: The concept is correct, but the implementation in `updateModelTime` has a subtle issue. `startOfDayReal` is initialized once in `setup` to the RTC's midnight of that day. If the Arduino runs for multiple *real* days, `elapsedReal` will keep growing, and `modelSeconds` will also keep growing, but `modelSeconds = modelSeconds % 86400;` only wraps the *calculated* model time, not the `startOfDayReal` reference. This means the model day will drift relative to the real day's midnight if the Arduino runs for more than 24 real hours. A better approach is to use `millis()` for elapsed time and reset a `realMillisAtModelMidnight` variable when the *model* day rolls over, or use the RTC's `now()` and calculate `elapsedRealSeconds` from a fixed `DateTime` reference. My solution uses `millis()` and updates `realMillisAtModelMidnight` when the model day rolls over.
    *   **Schedule Logic**: The `eventName` logic in `loop()` is problematic. `else if (modelMinutes >= 420 && modelMinutes < 480) eventName = "Bedroom TV Morning";` will never be reached if the previous `if` condition `(modelMinutes >= 420 && modelMinutes < 540)` is true, because 420-480 is a subset of 420-540. This means "Bedroom TV Morning" will never be displayed as the event name, it will always be "Morning Lights". The event names should be assigned carefully, perhaps prioritizing TV events over general lights if both are on.
    *   **Night TV Duration**: The `nightEnd` calculation `(nightModeFull ? 120 : 60)` correctly sets the end time in minutes past midnight. However, the condition `(modelMinutes >= 1320 && modelMinutes < 1440) || (modelMinutes >= 0 && modelMinutes < nightEnd)` is correct for handling the wrap-around.
    *   **`tvFlicker` function**: It uses `static unsigned long lastFlickerTime = 0;` and `static int flickerBrightness = 0;`. Since this function is called for *both* TV pins, these static variables will be shared, meaning both TVs will flicker in sync with the same brightness, which is not ideal for independent TV simulation. It should be passed an index or use an array of static variables. My solution uses an array for `lastFlickerMillis` and `flickerBrightness`.
    *   **`delay(200)` in `loop()`**: This delay will affect the responsiveness of the flicker and button reads. While `tvFlicker` has its own timing, a global `delay` can still make the system feel less responsive. A smaller delay or no delay with proper non-blocking timing is generally better.

2.  **Completeness**:
    *   Addresses all requirements: time acceleration, TV flicker, night mode, OLED display, RTC, continuous operation.
    *   Provides a good overview and step-by-step instructions.

3.  **Clarity and Step-by-Step Instructions**:
    *   Instructions are clear and well-structured.
    *   The table for hardware connections is helpful.
    *   The schedule table is a good idea, though the implementation needs refinement.

4.  **Code Quality**:
    *   The code is a good starting point.
    *   Variable naming is clear.
    *   Comments explain parts of the code.
    *   As noted above, the `tvFlicker` function has a bug due to shared static variables.
    *   The event name logic needs fixing.
    *   The time tracking could be more robust for long-term operation.

5.  **Helpfulness and Relevance**: Highly relevant and helpful, providing a complete solution structure.

6.  **Missing Information**:
    *   No explicit mention of current-limiting resistors for LEDs in the code or wiring table, though it's mentioned in a note. This is crucial.
    *   No implementation for changing the `timeAccelerationRatio` dynamically, which was requested ("with the option to change that ratio"). It's mentioned as an "Optional Enhancement" but not implemented.
    *   No implementation for the "night mode toggle" button, only a placeholder variable. It's mentioned as an "Optional Button". The prompt explicitly asked for "I want to be able to turn the night time code off".

**Critique of Assistant B's Answer**

1.  **Correctness and Accuracy**:
    *   **Time Acceleration**: The formula `simTime (in seconds) = simulationStartTime + (millis_elapsed * SIMULATION_FACTOR/1000)` is fundamentally flawed. `millis_elapsed` is in milliseconds. `SIMULATION_FACTOR` is a ratio (e.g., 6:1). If `SIMULATION_FACTOR` is 6, then `(millis_elapsed / 1000UL) * SIMULATION_FACTOR` means `(real_seconds) * 6`. This is correct. However, `simulationStartTime` is also in seconds. The `simStartMillis = millis();` in `setup()` correctly captures the real start time. The `simulationStartTime = 6 * 3600;` means the model clock *starts* at 06:00:00. This is a valid approach, but it means the model day doesn't necessarily align with real midnight. The prompt asked for "mimicking daily living... from the lights that turn on and off during a typical day", implying a 24-hour cycle that repeats. The current implementation will have the model day start at 06:00:00 model time, and then loop. This is okay, but the user might expect model 00:00 to be a reference.
    *   **RTC Usage**: The code initializes the RTC but then never reads from it. It relies solely on `millis()` for time tracking. The prompt explicitly states "we have an external rtc". This is a significant omission. The RTC should be used to provide a stable real-time reference, especially for long-running simulations, as `millis()` can drift or reset.
    *   **Flicker Effect**: The `flickerEffect()` function uses `random(0, 100) < 80` to return `true` or `false`. This only turns the LED fully ON or fully OFF, not a varying brightness flicker. The prompt asked for "a tv simulated light that flickers like a tv". A real TV flicker involves varying brightness, not just on/off. It also uses `random()` without `randomSeed()`, which means the sequence will be the same every time the Arduino starts.
    *   **Night Mode Logic**: The `NIGHT_MODE_PIN` is `INPUT_PULLUP`. `digitalRead(NIGHT_MODE_PIN) == HIGH` means the button is *not* pressed (or switch is open). So `nightModeEnabled` is true when the button is not pressed. The comment says `HIGH: default mode, bedtime event lasts 2 hours`. This aligns with the prompt's "turn the night time code off (reduce to 1hr)". So, if the button is pressed (LOW), `nightModeEnabled` is false, and `nightDuration` becomes 1 hour. This logic is correct.
    *   **Output Pins**: Only two output pins are defined (`LIVINGROOM_TV_PIN`, `BEDROOM_TV_PIN`). The prompt asked for "lights that turn on and off during a typical day" and "one in the living room for evening viewing and one in the bedroom for morning news and night viewing". This implies general house lights *and* TV lights. Assistant B only provides TV lights.
    *   **Schedule**: The schedule is very minimal (only 3 events, all TV-related). It doesn't include general house lights turning on/off.

2.  **Completeness**:
    *   Fails to use the RTC.
    *   Fails to implement general house lights, only TV lights.
    *   The TV flicker is just on/off, not varying brightness.
    *   The schedule is very basic and doesn't cover "daily living" beyond 3 TV events.
    *   No option to change the ratio dynamically, only to set it once.

3.  **Clarity and Step-by-Step Instructions**:
    *   Instructions are clear and well-formatted.
    *   The explanation of the simulation factor and time calculation is good, despite the RTC omission.

4.  **Code Quality**:
    *   The code is functional for what it implements.
    *   Good use of constants for event times.
    *   `timeToString` is a nice utility.
    *   The `flickerEffect` is too simplistic for "TV flicker".
    *   The `updateDisplay` function is good.

5.  **Helpfulness and Relevance**:
    *   Relevant to the core idea, but misses several key requirements from the prompt (RTC, general lights, proper flicker, dynamic ratio change).

6.  **Missing Information**:
    *   Crucially misses using the RTC.
    *   Misses general house lights.
    *   The TV flicker is not realistic (on/off vs. varying brightness).
    *   No dynamic ratio change.
    *   `randomSeed()` is missing for `random()`.
    *   No current-limiting resistors mentioned in the code or wiring for the LEDs.

**Comparison and Final Verdict**

Assistant A provides a more comprehensive solution that attempts to address all aspects of the prompt, including general house lights and a more realistic TV flicker (using `analogWrite` with random brightness). Its time acceleration logic, while having a minor long-term drift issue if not handled carefully, is closer to using the RTC as a reference. The main flaw in A is the shared static variables in `tvFlicker` and the event name logic. It also mentions the dynamic ratio change and night mode toggle as "optional enhancements" rather than implementing them directly, despite the prompt asking for them.

Assistant B misses several key requirements: it doesn't use the RTC at all, only implements TV lights (not general house lights), and its TV flicker is just on/off. Its time acceleration logic is simpler but also doesn't leverage the RTC. It does implement the night mode toggle, which is a plus.

Assistant A's approach to time management (using RTC `DateTime` objects) is more aligned with the prompt's "external rtc" requirement, even if its specific implementation of `startOfDayReal` could be more robust for multi-day real-time operation. Its `tvFlicker` function, despite the static variable bug, correctly uses `analogWrite` for varying brightness, which is what "flickers like a tv" implies. Assistant B's `flickerEffect` is just on/off.

Assistant A's code is closer to a complete solution for the prompt's requirements, even with its flaws. The issues in Assistant A are more about refinement and minor bugs, whereas Assistant B fundamentally misses core requirements like using the RTC and implementing general house lights.

My solution addresses the RTC usage, the `millis()`-based time acceleration with rollover handling, independent TV flicker, and all light outputs.

My final verdict is Assistant A is significantly better: [[A>>B]]

