```javascript
class Events {
    constructor() {
        this.subscribers = new Map();
    }

    subscribe(eventName, callback) {
        if (!this.subscribers.has(eventName)) {
            this.subscribers.set(eventName, []);
        }
        this.subscribers.get(eventName).push(callback);
    }

    unsubscribe(eventName, callback) {
        if (!this.subscribers.has(eventName)) {
            return;
        }

        const callbacks = this.subscribers.get(eventName);
        const index = callbacks.indexOf(callback);
        if (index !== -1) {
            callbacks.splice(index, 1);
        }

        if (callbacks.length === 0) {
            this.subscribers.delete(eventName);
        }
    }

    trigger(eventNames, ...options) {
        const namesToTrigger = Array.isArray(eventNames) ? eventNames : [eventNames];

        for (const eventName of namesToTrigger) {
            if (this.subscribers.has(eventName)) {
                const callbacks = this.subscribers.get(eventName);
                // Create a shallow copy to prevent issues if callbacks modify the subscription list during iteration
                [...callbacks].forEach(callback => {
                    try {
                        callback(...options);
                    } catch (error) {
                        console.error(`Error in callback for event "${eventName}":`, error);
                    }
                });
            }
        }
    }
}

