// Define a large value for infinity
const long long INF = std::numeric_limits<long long>::max();

// Dijkstra's algorithm to find shortest paths from a source node
// Returns a map from node to its shortest distance from 'start'
std::map<int, long long> dijkstra(int N, const std::vector<std::vector<std::pair<int, int>>>& graph, int start_node) {
    std::map<int, long long> distances;
    for (int i = 0; i < N; ++i) {
        distances[i] = INF;
    }
    distances[start_node] = 0;

    // Priority queue stores pairs of (distance, node)
    // Use std::greater to make it a min-priority queue
    std::priority_queue<std::pair<long long, int>,
                        std::vector<std::pair<long long, int>>,
                        std::greater<std::pair<long long, int>>> pq;
    pq.push({0, start_node});

    while (!pq.empty()) {
        long long current_dist = pq.top().first;
        int u = pq.top().second;
        pq.pop();

        if (current_dist > distances[u]) {
            continue;
        }

        for (const auto& edge : graph[u]) {
            int v = edge.first;
            int weight = edge.second;

            if (distances[u] + weight < distances[v]) {
                distances[v] = distances[u] + weight;
                pq.push({distances[v], v});
            }
        }
    }
    return distances;
}

