   * Updates permissions for a given user ID via API.
   * @param userId The ID of the user to update.
   * @param permissionPayload The permission data.
   * @returns The user credentials (username, password) after permission update.
   */
  async updateUserPermissions(userId: string, permissionPayload: PermissionPayload): Promise<UserCredentials> {
    console.log(`Updating permissions for user ID: ${userId} with payload:`, permissionPayload);
    const updatedPayload = { ...permissionPayload, id: userId }; // Merge ID into payload
    const res = await this.request.post('/users/v2/permissions', { data: updatedPayload });
