   * @param createPayload The initial user creation data.
   * @param permissionPayload The permission data to apply.
   * @returns The credentials of the created admin user.
   */
  async createAdminUser(createPayload: CreateUserPayload, permissionPayload: PermissionPayload): Promise<UserCredentials> {
    const userId = await this.createUser(createPayload);
    const credentials = await this.updateUserPermissions(userId, permissionPayload);
    return credentials;
  }
}

