// src/stores/tableStore.js
import { defineStore } from 'pinia';

export const useTableStore = defineStore('table', {
  state: () => ({
    rows: [],
    loading: false,
    hasMore: true, // Indicates if there are more rows to load
    currentPage: 0,
    pageSize: 20, // Number of rows to fetch per request
  }),
  actions: {
    async fetchRows() {
      if (this.loading || !this.hasMore) {
        return;
      }

      this.loading = true;
      try {
        // Simulate API call
        const start = this.currentPage * this.pageSize;
        const count = this.pageSize;

        // Replace with your actual API endpoint
        const response = await fetch(`/api/rows?start=${start}&count=${count}`);
        const data = await response.json();

        // Assuming data.rows is an array of new rows and data.total is the total count
        const newRows = data.rows;

        if (newRows.length < this.pageSize) {
          this.hasMore = false; // No more rows to load
        }

        this.rows.push(...newRows);
        this.currentPage++;
      } catch (error) {
        console.error("Error fetching rows:", error);
      } finally {
        this.loading = false;
      }
    },
    // Action to reset the store state, useful for re-fetching from the beginning
    resetStore() {
      this.rows = [];
      this.loading = false;
      this.hasMore = true;
      this.currentPage = 0;
    }
  }
});

