// stores/tableStore.js
import { defineStore } from 'pinia';
import axios from 'axios';

export const useTableStore = defineStore('table', {
  state: () => ({
    rows: [],
    isLoading: false,
    hasMore: true,
    currentPage: 0,
    pageSize: 20, // Number of rows to fetch per request
  }),
  actions: {
    async fetchRows() {
      if (this.isLoading || !this.hasMore) {
        return;
      }

      this.isLoading = true;
      try {
        // Simulate API call
        const response = await axios.get('/api/data', {
          params: {
            start: this.currentPage * this.pageSize,
            count: this.pageSize,
          },
        });

        const newRows = response.data.rows; // Assuming API returns { rows: [...] }
        this.rows.push(...newRows);

        if (newRows.length < this.pageSize) {
          this.hasMore = false; // No more data to load
        } else {
          this.currentPage++;
        }
      } catch (error) {
        console.error('Error fetching rows:', error);
        // Optionally handle error state
      } finally {
        this.isLoading = false;
      }
    },
    resetStore() {
      this.rows = [];
      this.isLoading = false;
      this.hasMore = true;
      this.currentPage = 0;
    },
  },
});

