#include <vector>
#include <algorithm> // For std::reverse

// Function to add two big numbers represented as strings
std::string addStrings(std::string num1, std::string num2) {
    std::string sum = "";
    int i = num1.length() - 1;
    int j = num2.length() - 1;
    int carry = 0;

    while (i >= 0 || j >= 0 || carry) {
        int digit1 = (i >= 0) ? num1[i--] - '0' : 0;
        int digit2 = (j >= 0) ? num2[j--] - '0' : 0;

        int currentSum = digit1 + digit2 + carry;
        sum += std::to_string(currentSum % 10);
        carry = currentSum / 10;
    }

    std::reverse(sum.begin(), sum.end());
    return sum;
}

// Function to compare two big numbers represented as strings
// Returns 1 if num1 > num2, -1 if num1 < num2, 0 if num1 == num2
int compareStrings(const std::string& num1, const std::string& num2) {
    if (num1.length() > num2.length()) {
        return 1;
    }
    if (num1.length() < num2.length()) {
        return -1;
    }
    // If lengths are equal, compare lexicographically
    if (num1 > num2) { // String comparison works lexicographically
        return 1;
    }
    if (num1 < num2) {
        return -1;
    }
    return 0; // They are equal
}

