#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <deque> // Not needed for my approach, but good to include if considering other greedy strategies

using namespace std;

// Node structure for the segment tree
struct Node {
    char val; // The character value
    int idx;  // The 1-indexed global operation index

    // Default constructor for sentinel values
    Node() : val('{'), idx(200001) {} // '{' is greater than 'z', INT_MAX for idx
    Node(char v, int i) : val(v), idx(i) {}
};

// Function to combine two nodes (find the minimum)
Node combine(const Node& left, const Node& right) {
    if (left.val < right.val) {
        return left;
    } else if (right.val < left.val) {
        return right;
    } else { // If values are equal, choose the one with smaller index
        return (left.idx < right.idx) ? left : right;
    }
}

// Segment tree implementation
vector<Node> tree;
vector<Node> arr_T; // Stores the T array (char, 1-indexed global op index)
int N_tree; // Size of the segment tree (power of 2 >= m)

void build(int m) {
    N_tree = 1;
    while (N_tree < m) {
        N_tree *= 2;
    }
    tree.assign(2 * N_tree, Node()); // Initialize with sentinel values

    // Fill leaf nodes
    for (int i = 0; i < m; ++i) {
        tree[N_tree + i] = arr_T[i];
    }

    // Build internal nodes
    for (int i = N_tree - 1; i > 0; --i) {
        tree[i] = combine(tree[2 * i], tree[2 * i + 1]);
    }
}

// Query for minimum in range [L, R] (1-indexed)
Node query(int l, int r) {
    Node res_left, res_right; // Sentinel values

    // Convert to 0-indexed for segment tree array access
    l += N_tree - 1; // l is 1-indexed, convert to 0-indexed then add N_tree for leaf node index
    r += N_tree - 1; // r is 1-indexed, convert to 0-indexed then add N_tree for leaf node index

    while (l <= r) {
        if (l % 2 == 1) { // l is a right child
            res_left = combine(res_left, tree[l]);
            l++;
        }
        if (r % 2 == 0) { // r is a left child
            res_right = combine(tree[r], res_right);
            r--;
        }
        l /= 2;
        r /= 2;
    }
    return combine(res_left, res_right);
}


int main() {
