        }
    }

    // If a has no '#', it remains unchanged.
    if (r_a == 0) {
        cout << a_str << "\n";
        return 0;
    }

    int r_b_needed = m - r_a; // Number of operations that must go to string b

    // Prepare the T array for segment tree
    arr_T.resize(m);
    for (int i = 0; i < m; ++i) {
        arr_T[i] = Node('a' + (i % 26), i + 1); // (char, 1-indexed global op index)
    }

    build(m); // Build the segment tree

    vector<int> chosen_ops_for_a(r_a);
    int prev_s_idx = 0; // The 1-indexed global operation index of the previously chosen op for 'a'

    for (int j = 1; j <= r_a; ++j) { // j-th '#' in string a
