#include <iostream>
#include <vector>
#include <algorithm>
#include <map> // For coordinate compression if needed, but vector + sort + unique + lower_bound is more common for y-coords

using namespace std;

typedef long long ll;
const int MOD = 1e9 + 7;

// Structure to represent a scanline event
struct Event {
    ll x;      // x-coordinate of the scanline
    int y1_idx; // Index of y1 in the discretized y-coordinates array
    int y2_idx; // Index of y2 in the discretized y-coordinates array
    int type;   // +1 for start of rectangle, -1 for end of rectangle

    // Custom comparator for sorting events by x-coordinate
    bool operator<(const Event& other) const {
        return x < other.x;
    }
};

// Segment Tree structure
struct SegmentTree {
    int n_intervals; // Number of elementary y-intervals
    vector<int> count; // Stores how many active rectangles cover this segment tree node's interval
    vector<ll> length; // Stores the total covered length within this segment tree node's interval
    const vector<ll>& y_coords; // Reference to the discretized y-coordinates

    SegmentTree(const vector<ll>& y_unique) : y_coords(y_unique) {
        n_intervals = y_unique.size() - 1; // Number of elementary intervals is (num_unique_y_coords - 1)
        count.assign(4 * n_intervals, 0);
        length.assign(4 * n_intervals, 0);
    }

    // Helper function to update the length of a node
    // idx: current node index in segment tree arrays
    // seg_l, seg_r: indices in y_coords array representing the interval [y_coords[seg_l], y_coords[seg_r])
    void pushup(int idx, int seg_l, int seg_r) {
        if (count[idx] > 0) {
            // If this node's interval is covered by at least one rectangle, its length is the full y-interval length
            length[idx] = y_coords[seg_r] - y_coords[seg_l];
        } else {
            // If not covered, its length is the sum of its children's lengths
            // If it's a leaf node (seg_r - seg_l == 1), then its length is 0
            if (seg_r - seg_l == 1) { // Leaf node
                length[idx] = 0;
            } else { // Internal node
                length[idx] = length[idx * 2] + length[idx * 2 + 1];
            }
        }
    }

    // Update the segment tree for a given query range [query_l, query_r)
    // idx: current node index
    // seg_l, seg_r: indices in y_coords array representing the current node's interval [y_coords[seg_l], y_coords[seg_r])
    // query_l, query_r: indices in y_coords array representing the interval to update [y_coords[query_l], y_coords[query_r])
    // val: +1 for adding coverage, -1 for removing coverage
    void update(int idx, int seg_l, int seg_r, int query_l, int query_r, int val) {
        // Current segment tree node's interval is outside the query range
        if (query_l >= seg_r || query_r <= seg_l) {
            return;
        }

        // Current segment tree node's interval is completely within the query range
        if (query_l <= seg_l && seg_r <= query_r) {
            count[idx] += val;
            pushup(idx, seg_l, seg_r); // Update length based on new count
            return;
        }

        // Current segment tree node's interval partially overlaps the query range, recurse
        int mid = seg_l + (seg_r - seg_l) / 2;
        update(idx * 2, seg_l, mid, query_l, query_r, val);
        update(idx * 2 + 1, mid, seg_r, query_l, query_r, val);

        pushup(idx, seg_l, seg_r); // After children are updated, update current node's length
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<vector<ll>> rectangles(n, vector<ll>(4));
    vector<ll> y_coordinates; // To collect all y-coordinates for discretization

    for (int i = 0; i < n; ++i) {
        cin >> rectangles[i][0] >> rectangles[i][1] >> rectangles[i][2] >> rectangles[i][3];
        y_coordinates.push_back(rectangles[i][1]);
        y_coordinates.push_back(rectangles[i][3]);
    }

    // Discretize y-coordinates
    sort(y_coordinates.begin(), y_coordinates.end());
    y_coordinates.erase(unique(y_coordinates.begin(), y_coordinates.end()), y_coordinates.end());

    // Create scanline events
    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        ll x1 = rectangles[i][0];
        ll y1 = rectangles[i][1];
        ll x2 = rectangles[i][2];
        ll y2 = rectangles[i][3];

        // Find indices for y1 and y2 in the discretized array
        int y1_idx = lower_bound(y_coordinates.begin(), y_coordinates.end(), y1) - y_coordinates.begin();
        int y2_idx = lower_bound(y_coordinates.begin(), y_coordinates.end(), y2) - y_coordinates.begin();

        // Add start and end events
        events.push_back({x1, y1_idx, y2_idx, 1});  // Type 1 for adding coverage
        events.push_back({x2, y1_idx, y2_idx, -1}); // Type -1 for removing coverage
    }

    // Sort events by x-coordinate
    sort(events.begin(), events.end());

    SegmentTree seg_tree(y_coordinates);
    ll total_area = 0;
    ll prev_x = events[0].x; // Start with the x-coordinate of the first event

    for (const auto& e : events) {
        ll current_x = e.x;
        ll dx = current_x - prev_x;

        // Calculate area contribution from the previous segment
        // The length[1] of the segment tree root gives the total covered length on the y-axis
        ll covered_y_length = seg_tree.length[1]; 

        // Add to total area, taking modulo at each step
        total_area = (total_area + (dx % MOD) * (covered_y_length % MOD)) % MOD;

        // Update the segment tree with the current event
        seg_tree.update(1, 0, seg_tree.n_intervals, e.y1_idx, e.y2_idx, e.type);

        prev_x = current_x; // Move prev_x to current_x for the next iteration
    }

    // Ensure the final result is non-negative
    cout << (total_area + MOD) % MOD << "\n";

    return 0;
}

