    // Pushes up information from children to parent
    // seg_left_idx and seg_right_idx are indices in the Y_coords array,
    // representing the elementary intervals [Y_coords[i], Y_coords[i+1])
    void pushup(int node_idx, int seg_left_idx, int seg_right_idx) {
        if (count[node_idx] > 0) { // If this node's interval is fully covered
            length[node_idx] = Y_coords[seg_right_idx + 1] - Y_coords[seg_left_idx];
        } else { // Not fully covered, sum children's lengths
            if (seg_left_idx == seg_right_idx) { // Leaf node, not covered
                length[node_idx] = 0;
            } else { // Internal node, sum children
                length[node_idx] = length[node_idx * 2] + length[node_idx * 2 + 1];
            }
        }
    }

    // Updates the segment tree for a given range [query_left_idx, query_right_idx]
    // val is +1 for adding a rectangle, -1 for removing
    // query_left_idx and query_right_idx are indices in Y_coords,
    // representing the range of elementary intervals [Y_coords[query_left_idx], Y_coords[query_left_idx+1]), ..., [Y_coords[query_right_idx], Y_coords[query_right_idx+1])
    void update(int node_idx, int seg_left_idx, int seg_right_idx,
                int query_left_idx, int query_right_idx, int val) {
        // Current segment tree node's interval is [Y_coords[seg_left_idx], Y_coords[seg_right_idx+1])
        // Query interval is [Y_coords[query_left_idx], Y_coords[query_right_idx+1])

        // No overlap
        if (query_left_idx > seg_right_idx || query_right_idx < seg_left_idx) {
            return;
        }

        // Current node's interval is fully contained within query interval
        if (query_left_idx <= seg_left_idx && seg_right_idx <= query_right_idx) {
            count[node_idx] += val;
            pushup(node_idx, seg_left_idx, seg_right_idx);
            return;
        }

        // Partial overlap, recurse
        int mid_idx = seg_left_idx + (seg_right_idx - seg_left_idx) / 2;
        update(node_idx * 2, seg_left_idx, mid_idx, query_left_idx, query_right_idx, val);
        update(node_idx * 2 + 1, mid_idx + 1, seg_right_idx, query_left_idx, query_right_idx, val);
        pushup(node_idx, seg_left_idx, seg_right_idx);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<array<long long, 4>> rectangles(n);
    vector<long long> y_coords_raw;
    y_coords_raw.reserve(2 * n);

    for (int i = 0; i < n; ++i) {
        cin >> rectangles[i][0] >> rectangles[i][1] >> rectangles[i][2] >> rectangles[i][3];
        y_coords_raw.push_back(rectangles[i][1]);
        y_coords_raw.push_back(rectangles[i][3]);
