    // Discretize Y-coordinates
    sort(y_coords_raw.begin(), y_coords_raw.end());
    y_coords_raw.erase(unique(y_coords_raw.begin(), y_coords_raw.end()), y_coords_raw.end());

    vector<Event> events;
    events.reserve(2 * n);

    for (const auto& rect : rectangles) {
