#include <string>
#include <vector>
#include <numeric> // For std::iota if needed, but manual fill is fine

class Solution {
public:
    string getPermutation(int n, int k) {
        // Precompute factorials
        // factorial[0] = 1, factorial[1] = 1, factorial[2] = 2, ..., factorial[n] = n!
        std::vector<int> factorial(n + 1);
        factorial[0] = 1;
        for (int i = 1; i <= n; ++i) {
            factorial[i] = factorial[i - 1] * i;
        }

        // Create a list of available numbers [1, 2, ..., n]
        std::vector<int> numbers;
        for (int i = 1; i <= n; ++i) {
            numbers.push_back(i);
        }

        // Adjust k to be 0-indexed
        k--;

        std::string result = "";

        // Iterate from n down to 1 to determine each digit
        for (int i = n; i >= 1; --i) {
            // Calculate the block size for the current position
            // This is (i-1)! because we are choosing one digit out of 'i' remaining digits,
            // and the rest (i-1) digits can be permuted in (i-1)! ways.
            int block_size = factorial[i - 1];

            // Determine the index of the digit to pick from the 'numbers' list
            int idx = k / block_size;

            // Append the chosen digit to the result string
            result += std::to_string(numbers[idx]);

            // Remove the chosen digit from the 'numbers' list
            numbers.erase(numbers.begin() + idx);

            // Update k for the next iteration (remaining permutations within the chosen block)
            k %= block_size;
        }

        return result;
    }
};

```

