#include <stdio.h>

// Hàm Euclide mở rộng
// Trả về d = gcd(a, b), đồng thời trả về x, y sao cho ax + by = d
void extendedEuclid(int a, int b, int *d, int *x, int *y) {
    // (1) Nếu b = 0 thì đặt d = a, x = 1, y = 0 và return (d, x, y)
    if (b == 0) {
        *d = a;
        *x = 1;
        *y = 0;
        return;
    }

    // (2) Đặt X2 = 1, X1 = 0, Y2 = 0, Y1 = 1
    int X2 = 1, X1 = 0;
    int Y2 = 0, Y1 = 1;
    int q, r;
    int tempX, tempY; // Biến tạm để lưu giá trị X, Y mới

    // (3) While b > 0 do
    while (b > 0) {
        // 3.1. q = [a/b], r = a - qb
        q = a / b;
        r = a - q * b;

        // X = X2 - qX1
        tempX = X2 - q * X1;
        // Y = Y2 - qY1
        tempY = Y2 - q * Y1;

        // 3.2. a = b, b = r, X2 = X1, X1 = X, Y2 = Y1, Y1 = Y
        a = b;
        b = r;

        X2 = X1;
        X1 = tempX; // Sử dụng tempX đã tính

        Y2 = Y1;
        Y1 = tempY; // Sử dụng tempY đã tính
    }

    // (4) Đặt d = a, x = X2, y = Y2 và return (d, x, y)
    *d = a;
    *x = X2;
    *y = Y2;
}

