void extendedEuclid(int a_orig, int b_orig, int *d, int *x, int *y) {
    int a = a_orig;
    int b = b_orig;

    if (b == 0) {
        *d = a;
        *x = 1;
        *y = 0;
        return;
    }

    int X2 = 1, X1 = 0;
