#include <numeric>
#include <algorithm>
#include <cmath>

// Function to check if a given base k is valid
bool isValidBase(long long k, long long a, long long b, long long c) {
    // k must be at least 2
    if (k < 2) {
        return false;
    }

    // Simulate digit-wise addition in base k
    while (a > 0 || b > 0 || c > 0) {
        long long digit_a = a % k;
        long long digit_b = b % k;
        long long digit_c = c % k;

        if ((digit_a + digit_b) % k != digit_c) {
            return false; // Mismatch in this digit position
        }

        a /= k;
        b /= k;
        c /= k;
    }
    return true; // All digit positions matched
}

